/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security guarantees:
 *   - Actual key VALUES are never read into memory beyond what is strictly
 *     required to rewrite the .env.test file line-by-line.
 *   - Key values are never stored in variables, logged, or returned.
 *   - rotation-log.json records only: timestamp, keyName, and a status/error.
 *   - The .env.test file is updated atomically: written to .env.test.tmp first,
 *     then renamed over the original so readers never see a partial file.
 *   - Generated placeholder values use Node's built-in `crypto` module so they
 *     are cryptographically random; no third-party dependencies are required.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── File paths (all relative to this module's directory) ────────────────────
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Keys that are eligible for rotation (read from .env.test at load time) ──
const ROTATEABLE_KEY_NAMES = _readRotateableKeyNames();

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Returns the list of key *names* (not values) found in .env.test that are
 * currently supported for rotation.
 *
 * @returns {string[]}
 */
function getSupportedKeys() {
  return [...ROTATEABLE_KEY_NAMES];
}

/**
 * Rotates the placeholder value for `keyName` in .env.test.
 *
 * Steps:
 *   1. Verify `keyName` is one of the supported keys.
 *   2. Generate a cryptographically random placeholder string.
 *   3. Rewrite .env.test to .env.test.tmp with the new placeholder on the
 *      matching line; all other lines are copied verbatim (values are never
 *      inspected or stored).
 *   4. Atomically rename .env.test.tmp → .env.test.
 *   5. Append a structured log entry (timestamp + keyName only) to
 *      rotation-log.json.
 *
 * @param {string} keyName  - The environment variable name to rotate,
 *                            e.g. "ANTHROPIC_API_KEY".
 * @throws {Error} If keyName is not supported, or if any I/O step fails.
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new Error('rotateKey: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEY_NAMES.has(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" is not a supported key. ` +
      `Supported keys: ${[...ROTATEABLE_KEY_NAMES].join(', ')}`
    );
  }

  // ── 2. Generate a new placeholder ─────────────────────────────────────────
  //   The placeholder format intentionally signals "not a real credential":
  //   ROTATED-<keyName prefix>-<32 hex chars>
  //   The prefix is derived from the key NAME (not value) for traceability.
  const namePart  = keyName.toLowerCase().replace(/_/g, '-').slice(0, 20);
  const randHex   = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  const newPlaceholder = `ROTATED-${namePart}-${randHex}`;
  // newPlaceholder never leaves this function except to be written to disk.

  // ── 3. Rewrite the file to a temp path ────────────────────────────────────
  _rewriteEnvFile(keyName, newPlaceholder);

  // ── 4. Atomic rename: .env.test.tmp → .env.test ───────────────────────────
  try {
    fs.renameSync(TMP_FILE, ENV_FILE);
  } catch (renameErr) {
    // Best-effort cleanup of the temp file before re-throwing.
    try { fs.unlinkSync(TMP_FILE); } catch (_) { /* ignore */ }
    throw new Error(
      `rotateKey: atomic rename failed for "${keyName}": ${renameErr.message}`
    );
  }

  // ── 5. Log the rotation event (key NAME + timestamp only) ─────────────────
  _appendLogEntry({
    timestamp : new Date().toISOString(),
    keyName,              // the variable name — safe to log
    status    : 'rotated',
    // NOTE: newPlaceholder and any actual key value are deliberately absent.
  });
}

// ── Private helpers ──────────────────────────────────────────────────────────

/**
 * Reads .env.test and returns a Set containing only the *names* of the two
 * target keys (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY) if they are present.
 * Values are discarded immediately and never stored.
 *
 * @returns {Set<string>}
 */
function _readRotateableKeyNames() {
  const TARGET_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const found = new Set();

  let raw;
  try {
    raw = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    // If the file doesn't exist yet, return an empty set gracefully.
    console.error(`key-rotation: could not read ${ENV_FILE}: ${err.message}`);
    return found;
  }

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed.includes('=')) continue;

    // Split on the FIRST '=' only; everything after is the value — which we
    // immediately discard by never assigning it to a named variable.
    const eqIdx   = trimmed.indexOf('=');
    const keyName = trimmed.slice(0, eqIdx).trim();
    // value is intentionally not captured

    if (TARGET_KEYS.has(keyName)) {
      found.add(keyName);
    }
  }

  return found;
}

/**
 * Reads .env.test line-by-line, replaces the value on the line whose name
 * matches `keyName` with `newPlaceholder`, and writes the result to TMP_FILE.
 *
 * SECURITY: lines for OTHER keys are written verbatim without ever being
 * parsed or stored — we never have all secrets in memory simultaneously as
 * named values.
 *
 * @param {string} keyName
 * @param {string} newPlaceholder
 */
function _rewriteEnvFile(keyName, newPlaceholder) {
  let raw;
  try {
    raw = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(
      `rotateKey: could not read ${ENV_FILE}: ${err.message}`
    );
  }

  const lines = raw.split('\n');
  let matched = false;

  const rewritten = lines.map((line) => {
    const trimmed = line.trim();

    // Preserve blank lines and comments exactly.
    if (trimmed.startsWith('#') || !trimmed.includes('=')) {
      return line;
    }

    const eqIdx        = trimmed.indexOf('=');
    const parsedName   = trimmed.slice(0, eqIdx).trim();
    // parsedValue is intentionally not captured for non-target lines

    if (parsedName === keyName) {
      matched = true;
      // Preserve any leading whitespace the original line had.
      const leading = line.match(/^(\s*)/)[1];
      return `${leading}${keyName}=${newPlaceholder}`;
    }

    // All other lines: return the original bytes — value never inspected.
    return line;
  });

  if (!matched) {
    throw new Error(
      `rotateKey: key "${keyName}" not found in ${ENV_FILE}. ` +
      'Has the file been modified externally?'
    );
  }

  try {
    fs.writeFileSync(TMP_FILE, rewritten.join('\n'), { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    throw new Error(
      `rotateKey: could not write temp file ${TMP_FILE}: ${err.message}`
    );
  }
}

/**
 * Appends `entry` to rotation-log.json as a JSON array.
 * Creates the file with an empty array if it does not yet exist.
 *
 * The function reads the existing log, pushes the new entry, and rewrites the
 * whole file — keeping the log human-readable and well-formed JSON.
 *
 * @param {{ timestamp: string, keyName: string, status: string }} entry
 */
function _appendLogEntry(entry) {
  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch (_) {
      // If the log is corrupt/empty, start fresh rather than crashing.
      log = [];
    }
  }

  log.push(entry);

  try {
    fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', {
      encoding : 'utf8',
      flag     : 'w',
    });
  } catch (err) {
    // Log write failure is non-fatal for the rotation itself, but we surface
    // it so operators can investigate.
    console.error(
      `key-rotation: WARNING — rotation succeeded but log write failed: ${err.message}`
    );
  }
}

// ── Module exports ───────────────────────────────────────────────────────────
module.exports = { rotateKey, getSupportedKeys };

