/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security invariants enforced throughout this module:
 *   - Actual key VALUES are never logged, printed, or included in any output.
 *   - Only key NAMES (the left-hand side of each KEY=value line) are handled
 *     outside of the atomic file-rewrite path.
 *   - The atomic write uses a sibling temp file + rename so a crash mid-write
 *     never leaves .env.test in a partially-written state.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Path constants
// ---------------------------------------------------------------------------
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Supported rotateable key names — populated by readRotateableKeyNames().
// ---------------------------------------------------------------------------
const ROTATEABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// 1. readRotateableKeyNames()
//
//    Parses .env.test and returns the subset of variable names that are
//    present in the file AND listed in ROTATEABLE_KEYS.
//    Returns: string[]  e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']
// ---------------------------------------------------------------------------
function readRotateableKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const found = [];

  for (const line of raw.split('\n')) {
    // Skip blank lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Extract the variable name (left of the first '=')
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const keyName = trimmed.slice(0, eqIdx).trim();
    if (ROTATEABLE_KEYS.has(keyName)) {
      found.push(keyName);
    }
  }

  return found;
}

// ---------------------------------------------------------------------------
// 2. generatePlaceholder(keyName)
//
//    Produces a new placeholder value that:
//      - Is clearly synthetic / non-production.
//      - Includes a short random hex suffix so successive rotations produce
//        distinct values (important for detecting stale-key usage).
//      - Never reflects or leaks the OLD value.
//
//    The placeholder format encodes the key name and a timestamp so the
//    rotation log and the env file can be correlated without exposing secrets.
// ---------------------------------------------------------------------------
function generatePlaceholder(keyName) {
  // 8 random bytes → 16 hex chars — enough entropy to be unique per rotation
  const randomSuffix = crypto.randomBytes(8).toString('hex');
  // ISO date compressed to YYYYMMDD for mild human readability
  const datePart = new Date().toISOString().slice(0, 10).replace(/-/g, '');

  // Build a prefix that mirrors the real-world format of each key type so
  // downstream validation code (if any) still recognises the shape.
  let prefix;
  switch (keyName) {
    case 'ANTHROPIC_API_KEY':
      prefix = 'REDACTED_ANTHROPIC_KEY';
      break;
    case 'STRIPE_SECRET_KEY':
      prefix = 'REDACTED_STRIPE_LIVE';
      break;
    default:
      prefix = 'ROTATED';
  }

  return `${prefix}-${datePart}-${randomSuffix}`;
}

// ---------------------------------------------------------------------------
// 3. rotateKey(keyName)
//
//    Core public function.
//
//    Steps:
//      a) Validate that keyName is in ROTATEABLE_KEYS and present in .env.test.
//      b) Read .env.test, locate the line for keyName, replace its value with
//         a new placeholder.
//      c) Write to .env.test.tmp, then atomically rename to .env.test.
//      d) Append a structured log entry (name + timestamp, NO value) to
//         rotation-log.json.
//
//    Returns: { keyName, rotatedAt }   (no value exposure)
//    Throws on any I/O or validation error.
// ---------------------------------------------------------------------------
function rotateKey(keyName) {
  // --- (a) Validate input -----------------------------------------------
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEYS.has(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" is not in the supported rotation set. ` +
      `Supported keys: ${[...ROTATEABLE_KEYS].join(', ')}.`
    );
  }

  // Confirm the key actually exists in the file before we do anything.
  const presentKeys = readRotateableKeyNames();
  if (!presentKeys.includes(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" not found in ${ENV_FILE}. ` +
      'Nothing was written.'
    );
  }

  // --- (b) Rewrite the env file content ---------------------------------
  const rawEnv  = fs.readFileSync(ENV_FILE, 'utf8');
  const newPlaceholder = generatePlaceholder(keyName);

  // Replace only the specific KEY=<value> assignment.
  // The regex matches the key name at the start of a line, the '=', then
  // everything up to (but not including) the newline — including any inline
  // comment that might follow the value.
  const linePattern = new RegExp(
    `^(${escapeRegExp(keyName)}=)(.*)$`,
    'm'
  );

  if (!linePattern.test(rawEnv)) {
    // Defensive: readRotateableKeyNames found it but regex didn't — shouldn't
    // happen, but guard anyway.
    throw new Error(
      `rotateKey: Could not locate the assignment line for "${keyName}" ` +
      'in the env file. Rotation aborted.'
    );
  }

  // $1 keeps "KEYNAME=", the old value ($2) is discarded — never stored.
  const newEnvContent = rawEnv.replace(linePattern, `$1${newPlaceholder}`);

  // --- (c) Atomic write: tmp file → rename ------------------------------
  // Write to .env.test.tmp first so a crash mid-write never corrupts
  // the live .env.test file.
  fs.writeFileSync(TMP_FILE, newEnvContent, { encoding: 'utf8', flag: 'w' });
  fs.renameSync(TMP_FILE, ENV_FILE);

  // --- (d) Append rotation event to rotation-log.json -------------------
  const rotatedAt = new Date().toISOString();
  appendRotationLog({ keyName, rotatedAt });

  // Return metadata only — deliberately omits the new placeholder value.
  return { keyName, rotatedAt };
}

// ---------------------------------------------------------------------------
// appendRotationLog({ keyName, rotatedAt })
//
//   Reads the existing log array (or starts a new one), pushes the new event,
//   and rewrites the file.  The log record contains ONLY:
//     - keyName   : the variable name (e.g. "ANTHROPIC_API_KEY")
//     - rotatedAt : ISO-8601 timestamp
//
//   Key VALUES are never present in any log entry.
// ---------------------------------------------------------------------------
function appendRotationLog({ keyName, rotatedAt }) {
  let logEntries = [];

  // Load existing log if present; start fresh if missing or malformed.
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
      // If it parsed but isn't an array, we reset — don't crash.
    } catch {
      // Malformed JSON — reset to empty array.
      logEntries = [];
    }
  }

  // Build the new entry — key name and timestamp ONLY.
  const entry = {
    keyName,      // e.g. "ANTHROPIC_API_KEY"
    rotatedAt,    // e.g. "2025-06-23T00:18:00.000Z"
    // NOTE: No 'newValue', 'oldValue', or any key material here.
  };

  logEntries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(logEntries, null, 2) + '\n', {
    encoding: 'utf8',
    flag: 'w',
  });
}

// ---------------------------------------------------------------------------
// Utility: escapeRegExp(str)
//   Escapes special regex characters in a string so it can be used safely
//   inside a RegExp constructor.
// ---------------------------------------------------------------------------
function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------
module.exports = {
  readRotateableKeyNames,
  rotateKey,
};

