/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Supports rotating keys that are declared in .env.test.
 * Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are eligible for rotation,
 * as those are the two keys whose variable names were discovered in .env.test.
 *
 * Security contract
 * -----------------
 *  • Actual key VALUES are never logged, printed, or included in any output.
 *  • rotation-log.json records only: timestamp, keyName, and a status string.
 *  • The .env.test file is updated atomically: a temp file (.env.test.tmp) is
 *    written first, then renamed over the original to avoid partial writes.
 *  • The generated placeholder follows the same structural prefix as the
 *    original value so downstream parsers keep working, but it is clearly
 *    marked as a placeholder (ROTATED-<timestamp>-<random-hex>) — never a
 *    real credential.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
const ENV_FILE      = path.resolve(__dirname, '.env.test');
const ENV_FILE_TMP  = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE      = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys that are eligible for rotation (discovered from .env.test)
// ---------------------------------------------------------------------------
const ROTATABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Parse a .env file into an ordered array of line descriptors so that
 * comments, blank lines, and key ordering are all preserved on rewrite.
 *
 * Each element is one of:
 *   { type: 'raw',   line: <original line string> }        // comment / blank
 *   { type: 'entry', key: <name>, value: <value>, line: <original line> }
 *
 * @param {string} content  Raw file content.
 * @returns {Array<object>}
 */
function parseEnvLines(content) {
  return content.split('\n').map((line) => {
    // Blank lines and comment lines are kept verbatim.
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      return { type: 'raw', line };
    }

    // KEY=VALUE  (value may contain '=')
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) {
      return { type: 'raw', line };
    }

    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1); // deliberately NOT trimmed — preserve quoting
    return { type: 'entry', key, value, line };
  });
}

/**
 * Serialise a parsed line array back to a .env file string.
 *
 * @param {Array<object>} lines
 * @returns {string}
 */
function serializeEnvLines(lines) {
  return lines.map((l) => (l.type === 'entry' ? `${l.key}=${l.value}` : l.line)).join('\n');
}

/**
 * Read and parse .env.test, returning the ordered line array.
 *
 * @returns {Array<object>}
 */
function readEnvFile() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  return parseEnvLines(raw);
}

/**
 * Write `content` to ENV_FILE atomically via a temp file + rename.
 *
 * @param {string} content
 */
function writeEnvFileAtomic(content) {
  fs.writeFileSync(ENV_FILE_TMP, content, { encoding: 'utf8', flag: 'w' });
  fs.renameSync(ENV_FILE_TMP, ENV_FILE);
}

/**
 * Append a rotation event object to rotation-log.json.
 * Creates the file (with an array) if it does not yet exist.
 *
 * The event object contains ONLY:
 *   - timestamp  (ISO-8601 string)
 *   - keyName    (variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("rotated" | "failed")
 *   - reason     (string, present only when status === "failed")
 *
 * KEY VALUES ARE NEVER WRITTEN HERE.
 *
 * @param {object} event
 */
function appendRotationLog(event) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    const raw = fs.readFileSync(LOG_FILE, 'utf8').trim();
    if (raw.length > 0) {
      entries = JSON.parse(raw); // will throw if the file is malformed
    }
  }

  if (!Array.isArray(entries)) {
    throw new TypeError('rotation-log.json must contain a JSON array at its root.');
  }

  entries.push(event);
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', { encoding: 'utf8', flag: 'w' });
}

/**
 * Generate a new key placeholder for a given key name.
 *
 * The placeholder is NOT a real credential; it follows the structural
 * prefix convention of the key family so that parsers recognise the
 * format, but is clearly marked as a rotated placeholder.
 *
 * Format:  <prefix>ROTATED-<isoTimestamp>-<8-hex-chars>
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomSuffix = crypto.randomBytes(4).toString('hex'); // 8 hex chars
  const ts           = new Date().toISOString().replace(/[:.]/g, '-'); // filesystem-safe

  const prefixMap = {
    ANTHROPIC_API_KEY : 'sk-ant-',
    STRIPE_SECRET_KEY : 'sk_live_',
  };

  const prefix = prefixMap[keyName] ?? 'key-';
  return `${prefix}ROTATED-${ts}-${randomSuffix}`;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read .env.test and return the set of variable names present in the file
 * that are also in the ROTATABLE_KEYS set.
 *
 * @returns {string[]}  e.g. ["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY"]
 */
function getRotatableKeys() {
  const lines = readEnvFile();
  return lines
    .filter((l) => l.type === 'entry' && ROTATABLE_KEYS.has(l.key))
    .map((l) => l.key);
}

/**
 * Rotate the value of `keyName` in .env.test.
 *
 * Steps:
 *  1. Validate that `keyName` is in the allowed ROTATABLE_KEYS set.
 *  2. Read and parse .env.test.
 *  3. Confirm the key is actually present in the file.
 *  4. Generate a new placeholder value.
 *  5. Update the in-memory line array (value only — position preserved).
 *  6. Serialise back to a string.
 *  7. Write atomically: ENV_FILE_TMP → rename → ENV_FILE.
 *  8. Append a log entry (timestamp + keyName + status) to rotation-log.json.
 *
 * Throws on any error; the log entry will carry status "failed" and a reason.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string, status: string }}
 */
function rotateKey(keyName) {
  const timestamp = new Date().toISOString();

  // --- 1. Validate key name ---
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const reason = 'keyName must be a non-empty string.';
    appendRotationLog({ timestamp, keyName: String(keyName), status: 'failed', reason });
    throw new TypeError(reason);
  }

  const normalizedKey = keyName.trim();

  if (!ROTATABLE_KEYS.has(normalizedKey)) {
    const reason = `"${normalizedKey}" is not in the permitted rotation set: ${[...ROTATABLE_KEYS].join(', ')}.`;
    appendRotationLog({ timestamp, keyName: normalizedKey, status: 'failed', reason });
    throw new Error(reason);
  }

  // --- 2. Parse .env.test ---
  let lines;
  try {
    lines = readEnvFile();
  } catch (err) {
    const reason = `Failed to read ${ENV_FILE}: ${err.message}`;
    appendRotationLog({ timestamp, keyName: normalizedKey, status: 'failed', reason });
    throw new Error(reason);
  }

  // --- 3. Locate the key ---
  const lineIndex = lines.findIndex((l) => l.type === 'entry' && l.key === normalizedKey);
  if (lineIndex === -1) {
    const reason = `Key "${normalizedKey}" was not found in ${ENV_FILE}.`;
    appendRotationLog({ timestamp, keyName: normalizedKey, status: 'failed', reason });
    throw new Error(reason);
  }

  // --- 4. Generate placeholder (never a real credential) ---
  const placeholder = generatePlaceholder(normalizedKey);

  // --- 5. Update the line in memory (value only; key name and position preserved) ---
  lines[lineIndex] = { type: 'entry', key: normalizedKey, value: placeholder };

  // --- 6. Serialise ---
  const newContent = serializeEnvLines(lines);

  // --- 7. Atomic write ---
  try {
    writeEnvFileAtomic(newContent);
  } catch (err) {
    const reason = `Atomic write failed: ${err.message}`;
    appendRotationLog({ timestamp, keyName: normalizedKey, status: 'failed', reason });
    throw new Error(reason);
  }

  // --- 8. Log rotation event (NO key values) ---
  const event = { timestamp, keyName: normalizedKey, status: 'rotated' };
  appendRotationLog(event);

  console.log(`[key-rotation] Rotated ${normalizedKey} at ${timestamp}`);
  return event;
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------
module.exports = { rotateKey, getRotatableKeys };

