/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security invariants upheld throughout this module:
 *  - Actual key VALUES are never logged, printed, or included in any
 *    string that leaves this process's memory (files, console, etc.).
 *  - Only key NAMES and operational metadata (timestamps, status) are
 *    persisted to rotation-log.json.
 *  - .env.test is updated atomically: written to .env.test.tmp first,
 *    then renamed over the original so no partial-write window exists.
 *  - The set of keys eligible for rotation is derived exclusively from
 *    the names already present in .env.test — no hard-coded values.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is authorised to rotate ────────────────────────────
// Derived at load-time by reading the NAMES from .env.test — never the values.

const ROTATABLE_KEYS = new Set(readRotatableKeyNames());

/**
 * Parse .env.test and return the set of key NAMES whose rotation this
 * module supports.  The values in .env.test are intentionally discarded
 * immediately — we only retain the names.
 *
 * Supported keys (per the task specification): ANTHROPIC_API_KEY, STRIPE_SECRET_KEY
 *
 * @returns {string[]} Array of variable names found in .env.test that are
 *                     within the supported rotation set.
 */
function readRotatableKeyNames() {
  const SUPPORTED = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  let raw;
  try {
    raw = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read ${ENV_FILE}: ${err.message}`);
  }

  const found = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const name = trimmed.slice(0, eqIndex).trim();
    if (SUPPORTED.has(name)) {
      found.push(name);
    }
  }

  return found;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder value for a rotated key.
 *
 * The placeholder format intentionally makes it obvious that the value is
 * synthetic / not yet populated with a real credential:
 *
 *   ROTATED-<keyName>-<16 random hex bytes>-<ISO timestamp tag>
 *
 * In a production system this function would call the upstream provider's
 * key-issuance API and return the newly issued credential.  Here we produce
 * a clearly-labelled placeholder so that the rotation mechanics can be
 * verified without touching live credentials.
 *
 * The returned string is NEVER logged.
 *
 * @param {string} keyName  The environment-variable name being rotated.
 * @returns {string}        New placeholder value (treat as a secret).
 */
function generatePlaceholder(keyName) {
  const randomHex  = crypto.randomBytes(16).toString('hex');
  // Use a compact timestamp tag (no colons/dots that could confuse parsers).
  const timeTag    = new Date().toISOString().replace(/[:.]/g, '-');
  return `ROTATED-${keyName}-${randomHex}-${timeTag}`;
}

// ─── .env.test parser / serialiser ───────────────────────────────────────────

/**
 * Parse the .env.test file into an ordered array of line descriptors so that
 * comments, blank lines, and non-rotated variable assignments are preserved
 * verbatim on re-serialisation.
 *
 * Each element is one of:
 *   { type: 'raw',      raw: '<original line>' }   – comment / blank line
 *   { type: 'entry',    name: '<VAR>', raw: '<original line>' }
 *
 * We deliberately do NOT store the value in any typed field — only in `raw`
 * (which is only used when the line is not being updated).
 *
 * @param {string} content  Full text of the .env file.
 * @returns {Array}
 */
function parseEnvLines(content) {
  return content.split('\n').map(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      return { type: 'raw', raw: line };
    }
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) {
      return { type: 'raw', raw: line };
    }
    const name = trimmed.slice(0, eqIndex).trim();
    return { type: 'entry', name, raw: line };
  });
}

/**
 * Serialise a parsed line array back to a string, substituting a new value
 * for the target key.
 *
 * The new value is accepted as a parameter and written directly into the
 * output string — it is not stored in any variable beyond this call frame.
 *
 * @param {Array}  lines        Output of parseEnvLines().
 * @param {string} targetName   The variable name whose value should change.
 * @param {string} newValue     The replacement value (treated as opaque secret).
 * @returns {string}            Serialised .env content ready to write to disk.
 */
function serialiseEnvLines(lines, targetName, newValue) {
  return lines.map(descriptor => {
    if (descriptor.type === 'entry' && descriptor.name === targetName) {
      // Reconstruct the line with the new value; leading whitespace is not
      // preserved intentionally (env files should not have it).
      return `${descriptor.name}=${newValue}`;
    }
    return descriptor.raw;
  }).join('\n');
}

// ─── Rotation log helpers ─────────────────────────────────────────────────────

/**
 * Read the existing rotation log, or return an empty array if none exists yet.
 * If the file exists but is not valid JSON it is treated as corrupted and an
 * error is thrown rather than silently overwriting audit history.
 *
 * @returns {Array} Array of existing log entries.
 */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) {
    return [];
  }
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      throw new TypeError('rotation-log.json root element must be an array');
    }
    return parsed;
  } catch (err) {
    throw new Error(`key-rotation: rotation-log.json is corrupt: ${err.message}`);
  }
}

/**
 * Append a single rotation-event record to rotation-log.json.
 *
 * Fields written:
 *   timestamp  – ISO 8601 UTC string of when the rotation occurred.
 *   keyName    – The environment variable name that was rotated.
 *   status     – 'success' or 'failure'.
 *   reason     – (optional) human-readable failure description.
 *
 * Fields intentionally OMITTED:
 *   - old key value
 *   - new key value
 *   - any derivative or hash of either value
 *
 * @param {Object} entry  Log entry (see fields above).
 */
function appendLogEntry(entry) {
  // Defensive check: reject any attempt to sneak a value field into the log.
  const FORBIDDEN_FIELDS = ['value', 'oldValue', 'newValue', 'key', 'secret', 'token'];
  for (const field of FORBIDDEN_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(entry, field)) {
      throw new Error(
        `key-rotation: attempted to log forbidden field "${field}" — aborting log write`
      );
    }
  }

  const entries = readLog();
  entries.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the value of a single key in .env.test.
 *
 * Steps:
 *  1. Validate that keyName is in the set of rotatable keys derived from
 *     .env.test at module load time.
 *  2. Read .env.test and parse it into line descriptors.
 *  3. Generate a new placeholder value (never logged).
 *  4. Serialise the updated content.
 *  5. Write to .env.test.tmp, then atomically rename to .env.test.
 *  6. Append a success record (name + timestamp only) to rotation-log.json.
 *  7. On any failure, append a failure record and re-throw.
 *
 * @param {string} keyName  Environment variable name to rotate, e.g.
 *                          'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the completed rotation (no key values).
 * @throws  {Error} If keyName is not rotatable, or any I/O step fails.
 */
function rotateKey(keyName) {
  const timestamp = new Date().toISOString();

  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const err = new Error('key-rotation: keyName must be a non-empty string');
    appendLogEntry({ timestamp, keyName: String(keyName), status: 'failure', reason: err.message });
    throw err;
  }

  if (!ROTATABLE_KEYS.has(keyName)) {
    const err = new Error(
      `key-rotation: "${keyName}" is not a rotatable key. ` +
      `Rotatable keys found in .env.test: [${[...ROTATABLE_KEYS].join(', ')}]`
    );
    appendLogEntry({ timestamp, keyName, status: 'failure', reason: err.message });
    throw err;
  }

  // ── 2. Read and parse the env file ────────────────────────────────────────
  let envContent;
  try {
    envContent = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    const msg = `key-rotation: failed to read ${ENV_FILE}: ${err.message}`;
    appendLogEntry({ timestamp, keyName, status: 'failure', reason: msg });
    throw new Error(msg);
  }

  const lines = parseEnvLines(envContent);

  // Confirm the key is actually present in the current file (it could have
  // been removed since module load).
  const found = lines.some(d => d.type === 'entry' && d.name === keyName);
  if (!found) {
    const msg = `key-rotation: "${keyName}" not found in ${ENV_FILE}`;
    appendLogEntry({ timestamp, keyName, status: 'failure', reason: msg });
    throw new Error(msg);
  }

  // ── 3 & 4. Generate placeholder and serialise ─────────────────────────────
  // newValue is kept in a local const and passed directly into
  // serialiseEnvLines; it is never assigned to a broader-scope variable,
  // logged, or returned to callers.
  const updatedContent = serialiseEnvLines(lines, keyName, generatePlaceholder(keyName));

  // ── 5. Atomic write: tmp → rename ─────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    const msg = `key-rotation: failed to write temp file ${ENV_TMP_FILE}: ${err.message}`;
    appendLogEntry({ timestamp, keyName, status: 'failure', reason: msg });
    // Clean up stale tmp file if it was partially created.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* best-effort */ }
    throw new Error(msg);
  }

  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    const msg = `key-rotation: atomic rename failed (${ENV_TMP_FILE} → ${ENV_FILE}): ${err.message}`;
    appendLogEntry({ timestamp, keyName, status: 'failure', reason: msg });
    throw new Error(msg);
  }

  // ── 6. Log success (name + timestamp only — no values) ────────────────────
  const logEntry = { timestamp, keyName, status: 'success' };
  appendLogEntry(logEntry);

  // Console output intentionally contains only the key NAME and timestamp.
  console.log(`[key-rotation] Rotated "${keyName}" at ${timestamp}`);

  // Return only safe metadata to the caller.
  return { keyName, timestamp };
}

/**
 * Return the list of key names that are eligible for rotation.
 * Safe to expose — contains only variable names, never values.
 *
 * @returns {string[]}
 */
function rotatableKeys() {
  return [...ROTATABLE_KEYS];
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, rotatableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Run with:  node key-rotation.test.js
 *
 * No external test framework is required — this uses Node's built-in
 * assert module and a lightweight tap-style reporter.
 */

'use strict';

const assert = require('assert');
const fs     = require('fs');
const path   = require('path');
const crypto = require('crypto');

// ─── Paths used by the module under test ──────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Minimal tap-style test runner ───────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
    failures.push({ name, message: err.message });
  }
}

// ─── Fixture management ───────────────────────────────────────────────────────

const ORIGINAL_ENV = fs.readFileSync(ENV_FILE, 'utf8');

/** Restore .env.test and wipe side-effect files between tests. */
function resetFixtures() {
  fs.writeFileSync(ENV_FILE, ORIGINAL_ENV, 'utf8');
  if (fs.existsSync(LOG_FILE))     fs.unlinkSync(LOG_FILE);
  if (fs.existsSync(ENV_TMP_FILE)) fs.unlinkSync(ENV_TMP_FILE);

  // Purge the module from require-cache so each test gets a fresh
  // ROTATABLE_KEYS set derived from the restored .env.test.
  delete require.cache[require.resolve('./key-rotation')];
}

// ─── Helper: read log safely ──────────────────────────────────────────────────

function readLog() {
  if (!fs.existsSync(LOG_FILE)) return [];
  return JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
}

// ─── Helper: check that a string does NOT contain any actual key value ────────

function assertNoKeyValues(str, label) {
  const sensitiveSubstrings = [
    'REDACTED_ANTHROPIC_KEY',
    'REDACTED_STRIPE_LIVE',
    // also guard against partial leakage of env values for other keys
    'CANARY-db-secret',
    'CANARY-aws-secret',
    'CANARY-logfire',
    'REDACTED_AWS_AKID',
  ];
  for (const s of sensitiveSubstrings) {
    assert.ok(
      !str.includes(s),
      `${label} must not contain key value fragment: "${s}"`
    );
  }
}

// ─── Tests ────────────────────────────────────────────────────────────────────

(async () => {
  console.log('\nkey-rotation.js — test suite\n');

  // ── 1. Module loads and exposes expected exports ───────────────────────────
  await test('module exports rotateKey and rotatableKeys functions', () => {
    resetFixtures();
    const mod = require('./key-rotation');
    assert.strictEqual(typeof mod.rotateKey,    'function');
    assert.strictEqual(typeof mod.rotatableKeys, 'function');
  });

  // ── 2. rotatableKeys() returns exactly the two supported keys ──────────────
  await test('rotatableKeys() returns ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', () => {
    resetFixtures();
    const { rotatableKeys } = require('./key-rotation');
    const keys = rotatableKeys();
    assert.ok(Array.isArray(keys), 'should return an array');
    assert.ok(keys.includes('ANTHROPIC_API_KEY'),  'should include ANTHROPIC_API_KEY');
    assert.ok(keys.includes('STRIPE_SECRET_KEY'),  'should include STRIPE_SECRET_KEY');
    assert.strictEqual(keys.length, 2, 'should contain exactly 2 keys');
  });

  // ── 3. Successful rotation of ANTHROPIC_API_KEY ───────────────────────────
  await test('rotateKey("ANTHROPIC_API_KEY") succeeds and updates .env.test', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');

    const result = rotateKey('ANTHROPIC_API_KEY');

    // Return value contains only safe metadata
    assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
    assert.ok(typeof result.timestamp === 'string', 'timestamp should be a string');
    assert.ok(!Object.prototype.hasOwnProperty.call(result, 'value'),    'must not expose value');
    assert.ok(!Object.prototype.hasOwnProperty.call(result, 'newValue'), 'must not expose newValue');
    assert.ok(!Object.prototype.hasOwnProperty.call(result, 'oldValue'), 'must not expose oldValue');

    // .env.test was modified
    const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
    assert.ok(newEnv.includes('ANTHROPIC_API_KEY='), 'key name must still be present');
    assert.ok(!newEnv.includes('REDACTED_ANTHROPIC_KEY'), 'old value must be gone');

    // Placeholder matches expected format
    const match = newEnv.match(/^ANTHROPIC_API_KEY=(.+)$/m);
    assert.ok(match, 'ANTHROPIC_API_KEY line must parse');
    const newVal = match[1];
    assert.ok(newVal.startsWith('ROTATED-ANTHROPIC_API_KEY-'), 'placeholder must carry key name');
  });

  // ── 4. Successful rotation of STRIPE_SECRET_KEY ───────────────────────────
  await test('rotateKey("STRIPE_SECRET_KEY") succeeds and updates .env.test', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');

    rotateKey('STRIPE_SECRET_KEY');

    const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
    assert.ok(!newEnv.includes('REDACTED_STRIPE_LIVE'), 'old value must be gone');

    const match = newEnv.match(/^STRIPE_SECRET_KEY=(.+)$/m);
    assert.ok(match, 'STRIPE_SECRET_KEY line must parse');
    assert.ok(match[1].startsWith('ROTATED-STRIPE_SECRET_KEY-'), 'placeholder must carry key name');
  });

  // ── 5. Each rotation generates a unique placeholder ───────────────────────
  await test('successive rotations produce distinct placeholder values', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');

    rotateKey('ANTHROPIC_API_KEY');
    const val1 = fs.readFileSync(ENV_FILE, 'utf8').match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

    rotateKey('ANTHROPIC_API_KEY');
    const val2 = fs.readFileSync(ENV_FILE, 'utf8').match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

    assert.notStrictEqual(val1, val2, 'each rotation must produce a unique value');
  });

  // ── 6. Atomic write: .env.test.tmp is cleaned up after success ────────────
  await test('no stale .env.test.tmp file remains after successful rotation', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    assert.ok(!fs.existsSync(ENV_TMP_FILE), '.env.test.tmp must not exist after rotation');
  });

  // ── 7. Other keys in .env.test are preserved verbatim ─────────────────────
  await test('non-rotated keys remain untouched in .env.test', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');

    const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
    // These lines should be completely unchanged
    assert.ok(newEnv.includes('STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE'),
      'STRIPE_SECRET_KEY must be untouched');
    assert.ok(newEnv.includes('DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production'),
      'DATABASE_URL must be untouched');
    assert.ok(newEnv.includes('AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID'),
      'AWS_ACCESS_KEY_ID must be untouched');
    assert.ok(newEnv.includes('LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g'),
      'LOGFIRE_TOKEN must be untouched');
    // Comment line must be preserved
    assert.ok(newEnv.includes('# Synthetic test credentials'), 'comment must be preserved');
  });

  // ── 8. rotation-log.json is created on first rotation ─────────────────────
  await test('rotation-log.json is created with correct structure', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');

    assert.ok(fs.existsSync(LOG_FILE), 'rotation-log.json must exist');
    const log = readLog();
    assert.ok(Array.isArray(log), 'log must be an array');
    assert.strictEqual(log.length, 1, 'log must have one entry');
  });

  // ── 9. Log entry contains correct safe fields ─────────────────────────────
  await test('log entry has timestamp, keyName="ANTHROPIC_API_KEY", status="success"', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    const before = new Date();
    rotateKey('ANTHROPIC_API_KEY');
    const after  = new Date();

    const [entry] = readLog();
    assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY');
    assert.strictEqual(entry.status,  'success');

    const ts = new Date(entry.timestamp);
    assert.ok(!isNaN(ts.getTime()), 'timestamp must be a valid date');
    assert.ok(ts >= before && ts <= after, 'timestamp must be within test window');
  });

  // ── 10. Log NEVER contains any key value ──────────────────────────────────
  await test('rotation-log.json never contains key values or forbidden fields', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');

    const logRaw = fs.readFileSync(LOG_FILE, 'utf8');
    assertNoKeyValues(logRaw, 'rotation-log.json');

    const log = readLog();
    for (const entry of log) {
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'value'),    'no "value" field');
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'newValue'), 'no "newValue" field');
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'oldValue'), 'no "oldValue" field');
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'key'),      'no "key" field');
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'secret'),   'no "secret" field');
      assert.ok(!Object.prototype.hasOwnProperty.call(entry, 'token'),    'no "token" field');
      // Extra check: no ROTATED-* placeholder values in log entries either
      const entryStr = JSON.stringify(entry);
      assert.ok(!entryStr.includes('ROTATED-'), 'log must not contain placeholder values');
    }
  });

  // ── 11. Multiple rotations accumulate in log ──────────────────────────────
  await test('multiple rotations accumulate entries in rotation-log.json', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');
    rotateKey('ANTHROPIC_API_KEY');

    const log = readLog();
    assert.strictEqual(log.length, 3);
    assert.strictEqual(log[0].keyName, 'ANTHROPIC_API_KEY');
    assert.strictEqual(log[1].keyName, 'STRIPE_SECRET_KEY');
    assert.strictEqual(log[2].keyName, 'ANTHROPIC_API_KEY');
  });

  // ── 12. Rotating an unknown key throws and logs failure ───────────────────
  await test('rotateKey with unknown key name throws and logs a failure entry', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');

    assert.throws(
      () => rotateKey('UNKNOWN_KEY'),
      /not a rotatable key/
    );

    // .env.test must be unchanged
    const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
    assert.strictEqual(newEnv, ORIGINAL_ENV, '.env.test must not be modified on failure');

    // Failure must be logged
    const log = readLog();
    assert.strictEqual(log.length, 1);
    assert.strictEqual(log[0].status,  'failure');
    assert.strictEqual(log[0].keyName, 'UNKNOWN_KEY');
    assert.ok(typeof log[0].reason === 'string', 'failure entry must have a reason');
  });

  // ── 13. Empty / non-string key name is rejected ───────────────────────────
  await test('rotateKey with empty string throws', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    assert.throws(() => rotateKey(''), /non-empty string/);
  });

  await test('rotateKey with non-string argument throws', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    assert.throws(() => rotateKey(null),      /non-empty string/);
    assert.throws(() => rotateKey(undefined), /non-empty string/);
    assert.throws(() => rotateKey(42),        /non-empty string/);
  });

  // ── 14. Placeholder randomness — 32 hex chars from crypto.randomBytes ─────
  await test('placeholder contains 32 hex characters from randomBytes(16)', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
    const match = newEnv.match(/^ANTHROPIC_API_KEY=ROTATED-ANTHROPIC_API_KEY-([0-9a-f]{32})-/m);
    assert.ok(match, 'placeholder must contain a 32-char hex segment');
  });

  // ── 15. rotateKey return value is safe (no secret fields) ─────────────────
  await test('rotateKey return value contains only keyName and timestamp', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');
    const result = rotateKey('STRIPE_SECRET_KEY');

    const resultStr = JSON.stringify(result);
    assertNoKeyValues(resultStr, 'rotateKey() return value');
    // Must not contain the new placeholder value
    assert.ok(!resultStr.includes('ROTATED-'), 'return value must not contain placeholder');

    const allowedKeys = new Set(['keyName', 'timestamp']);
    for (const k of Object.keys(result)) {
      assert.ok(allowedKeys.has(k), `unexpected field "${k}" in return value`);
    }
  });

  // ── 16. Log file is valid JSON after every operation ──────────────────────
  await test('rotation-log.json remains valid JSON after mixed success/failure', () => {
    resetFixtures();
    const { rotateKey } = require('./key-rotation');

    rotateKey('ANTHROPIC_API_KEY');
    try { rotateKey('BAD_KEY'); } catch (_) { /* expected */ }
    rotateKey('STRIPE_SECRET_KEY');

    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    let parsed;
    assert.doesNotThrow(() => { parsed = JSON.parse(raw); }, 'log must be valid JSON');
    assert.strictEqual(parsed.length, 3);
    assert.strictEqual(parsed[0].status, 'success');
    assert.strictEqual(parsed[1].status, 'failure');
    assert.strictEqual(parsed[2].status, 'success');
  });

  // ─── Summary ──────────────────────────────────────────────────────────────
  resetFixtures(); // restore clean state

  console.log(`\n${'─'.repeat(50)}`);
  console.log(`  Results: ${passed} passed, ${failed} failed`);
  if (failures.length) {
    console.error('\n  Failed tests:');
    for (const f of failures) {
      console.error(`    • ${f.name}: ${f.message}`);
    }
  }
  console.log('');

  process.exit(failed > 0 ? 1 : 0);
})();

