/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Responsibilities:
 *  1. Read .env.test to discover which key names are present.
 *  2. rotateKey(keyName) – generate a new placeholder value for a known key,
 *     write the updated file atomically (tmp → rename), and log the event.
 *  3. Append a structured rotation event (timestamp + key NAME only) to
 *     rotation-log.json.
 *
 * Security invariant: actual key values are NEVER logged, printed, or
 * returned to callers.  Only key *names* appear in logs.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = ENV_FILE + '.tmp';
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Parse an .env file into a Map<name, {value, rawLine, lineIndex}>.
 * Lines that are blank or start with '#' are preserved verbatim; only
 * `KEY=value` lines are parsed.
 *
 * @param {string} content  Raw file content.
 * @returns {{ entries: Map<string, {value:string, lineIndex:number}>,
 *             lines: string[] }}
 */
function parseEnv(content) {
  const lines   = content.split('\n');
  const entries = new Map();

  lines.forEach((line, idx) => {
    // Skip blanks and comments
    if (!line.trim() || line.trim().startsWith('#')) return;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) return;

    const name  = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1); // preserve everything after '='
    entries.set(name, { value, lineIndex: idx });
  });

  return { entries, lines };
}

/**
 * Serialise a lines array back to a file string (no trailing newline added
 * beyond what was already there).
 *
 * @param {string[]} lines
 * @returns {string}
 */
function serialiseEnv(lines) {
  return lines.join('\n');
}

/**
 * Generate a new opaque placeholder value for a rotated key.
 *
 * The value is a hex string derived from cryptographically random bytes so
 * it is both unique and unpredictable.  A short semantic prefix is included
 * so the origin of the placeholder is obvious when a human inspects the file.
 *
 * @returns {string}
 */
function generatePlaceholder() {
  // 32 random bytes → 64 hex chars  (256 bits of entropy)
  const randomHex = crypto.randomBytes(32).toString('hex');
  return `ROTATED-PLACEHOLDER-${randomHex}`;
}

/**
 * Atomically write content to `targetPath` by writing to a sibling `.tmp`
 * file first, then renaming.  On POSIX systems rename(2) is atomic with
 * respect to other readers of `targetPath`.
 *
 * @param {string} targetPath  Final destination.
 * @param {string} tmpPath     Temporary file (same filesystem as target).
 * @param {string} content     Data to write.
 */
function atomicWrite(targetPath, tmpPath, content) {
  // Write to the temp file (will truncate/create)
  fs.writeFileSync(tmpPath, content, { encoding: 'utf8', flag: 'w' });
  // Rename is atomic on the same filesystem
  fs.renameSync(tmpPath, targetPath);
}

/**
 * Append a rotation event to rotation-log.json.
 * The log is a JSON array; if the file does not exist it is created.
 * Only the key *name* and a UTC timestamp are recorded – never the value.
 *
 * @param {string} keyName  Name of the rotated key (e.g. "ANTHROPIC_API_KEY").
 */
function appendRotationLog(keyName) {
  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8').trim();
      if (raw) {
        log = JSON.parse(raw);
        if (!Array.isArray(log)) {
          throw new TypeError('rotation-log.json root element is not an array');
        }
      }
    } catch (err) {
      // Corrupt log – surface the error rather than silently overwriting.
      throw new Error(`Failed to read existing rotation log: ${err.message}`);
    }
  }

  /** @type {RotationEvent} */
  const event = {
    timestamp: new Date().toISOString(), // UTC, ISO-8601
    keyName,                             // name only – never the value
  };

  log.push(event);

  // Pretty-print so the file is human-readable in a text editor
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Read .env.test and return the list of key names that are present.
 * Values are intentionally not returned.
 *
 * @returns {string[]}  Array of key names, e.g. ["ANTHROPIC_API_KEY", …]
 */
function readKeyNames() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file not found: ${ENV_FILE}`);
  }

  const content         = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries }     = parseEnv(content);
  return Array.from(entries.keys());
}

/**
 * Rotate a single key in .env.test.
 *
 * Steps:
 *  1. Read and parse .env.test.
 *  2. Verify that `keyName` exists in the file.
 *  3. Replace its value with a freshly generated placeholder.
 *  4. Write the updated content atomically via .env.test.tmp → rename.
 *  5. Append a log entry (timestamp + name) to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation event (name + time; never the new value).
 * @throws {Error} If the key is not found in .env.test or I/O fails.
 */
function rotateKey(keyName) {
  if (!keyName || typeof keyName !== 'string') {
    throw new TypeError(`keyName must be a non-empty string, got: ${JSON.stringify(keyName)}`);
  }

  // ── 1. Read current file ──────────────────────────────────────────────────
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file not found: ${ENV_FILE}`);
  }
  const originalContent = fs.readFileSync(ENV_FILE, 'utf8');

  // ── 2. Parse ──────────────────────────────────────────────────────────────
  const { entries, lines } = parseEnv(originalContent);

  if (!entries.has(keyName)) {
    const known = Array.from(entries.keys()).join(', ');
    throw new Error(
      `Key "${keyName}" not found in ${ENV_FILE}. ` +
      `Known keys: ${known}`
    );
  }

  // ── 3. Replace the value on the relevant line ─────────────────────────────
  const { lineIndex } = entries.get(keyName);
  const placeholder   = generatePlaceholder();

  // Reconstruct the line preserving the exact key spelling
  lines[lineIndex] = `${keyName}=${placeholder}`;

  // ── 4. Atomic write ───────────────────────────────────────────────────────
  const updatedContent = serialiseEnv(lines);
  atomicWrite(ENV_FILE, ENV_TMP_FILE, updatedContent);

  // ── 5. Log the event (name + timestamp ONLY) ──────────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName);

  // Return metadata – caller never receives the placeholder value
  return { keyName, timestamp };
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = { rotateKey, readKeyNames };

// ─── CLI entry-point ──────────────────────────────────────────────────────────
// Allow direct invocation:  node key-rotation.js <KEY_NAME>
//                       or: node key-rotation.js --list
if (require.main === module) {
  const [,, ...args] = process.argv;

  if (args[0] === '--list') {
    const names = readKeyNames();
    console.log('Keys present in .env.test:');
    names.forEach(n => console.log(`  • ${n}`));
    process.exit(0);
  }

  if (args.length === 0) {
    console.error('Usage: node key-rotation.js <KEY_NAME>');
    console.error('       node key-rotation.js --list');
    process.exit(1);
  }

  const keyName = args[0];
  try {
    const result = rotateKey(keyName);
    console.log(`[${result.timestamp}] Rotated key: ${result.keyName}`);
  } catch (err) {
    console.error(`Rotation failed: ${err.message}`);
    process.exit(1);
  }
}

