/**
 * key-rotation.js
 *
 * API key rotation mechanism for managed environment variables.
 *
 * Security contract:
 *   - Actual key VALUES are never logged, printed, stored in memory longer than
 *     necessary, or appear in any audit record.
 *   - Only key NAMES and rotation metadata are written to rotation-log.json.
 *   - The .env.test file is updated atomically: a temporary file is written
 *     first, then renamed over the original so a crash mid-write can never
 *     leave the file in a partially-written state.
 *   - The temporary file (.env.test.tmp) is removed on every error path so it
 *     cannot be left behind with sensitive content on disk.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is authorised to rotate ────────────────────────────
//
// Populated at module load by readManagedKeyNames().  Only these names may be
// passed to rotateKey(); anything else is rejected to prevent accidental
// rotation of unrelated variables.

let managedKeyNames = [];   // filled by readManagedKeyNames()

// ─── Target key names to look for in .env.test ────────────────────────────────
//
// The specification states that ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are the
// keys that "need rotation support".  We look specifically for these two names
// in the env file so that the set of rotatable keys is derived from the file
// itself (they must already be present), not hard-coded as a static list.

const ROTATION_CANDIDATES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ─── Placeholder prefix map ───────────────────────────────────────────────────
//
// Each key type has a recognisable, service-specific prefix so that the
// generated placeholder looks structurally consistent with real credentials of
// that type (useful for downstream validation regexes) while being clearly
// synthetic.

const KEY_PREFIXES = {
  ANTHROPIC_API_KEY:  'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY:  'REDACTED_STRIPE_LIVE',
};

const DEFAULT_PREFIX = 'ROTATED-KEY-';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of line descriptors so that the
 * file can be reconstructed with every comment, blank line, and ordering
 * preserved exactly.
 *
 * Each element is one of:
 *   { type: 'raw',   content: '<original line text>' }   – comment / blank
 *   { type: 'entry', key: '<NAME>', value: '<VALUE>',
 *                    raw: '<original line text>' }        – KEY=VALUE pair
 *
 * Values are stored but NEVER logged or returned to callers.
 *
 * @param {string} text - Raw file contents.
 * @returns {Array<object>}
 */
function parseEnvLines(text) {
  return text.split('\n').map(line => {
    // Blank lines and comments are kept verbatim.
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      return { type: 'raw', content: line };
    }

    // KEY=VALUE (value may itself contain '=').
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) {
      // Malformed line – preserve as-is.
      return { type: 'raw', content: line };
    }

    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1);          // intentionally not trimmed
                                                   // to preserve quoted values

    // Reject keys that contain whitespace – those are almost certainly comment
    // lines that happen to have an '=' sign further along.
    if (/\s/.test(key)) {
      return { type: 'raw', content: line };
    }

    return { type: 'entry', key, value, raw: line };
  });
}

/**
 * Serialise a parsed line array back to a .env file string.
 *
 * @param {Array<object>} lines
 * @returns {string}
 */
function serializeEnvLines(lines) {
  return lines.map(line => {
    if (line.type === 'raw')   return line.content;
    if (line.type === 'entry') return `${line.key}=${line.value}`;
    return line.content;   // fallback
  }).join('\n');
}

/**
 * Read the .env.test file and return the subset of ROTATION_CANDIDATES that
 * are actually present in the file.  This is what populates `managedKeyNames`.
 *
 * Throws if the file cannot be read.
 *
 * @returns {string[]}
 */
function readManagedKeyNames() {
  let raw;
  try {
    raw = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(
      `key-rotation: cannot read ${ENV_FILE}: ${err.message}`
    );
  }

  const lines   = parseEnvLines(raw);
  const present = new Set(
    lines
      .filter(l => l.type === 'entry')
      .map(l => l.key)
  );

  return ROTATION_CANDIDATES.filter(name => present.has(name));
}

/**
 * Generate a cryptographically random placeholder value for the given key name.
 * The generated string intentionally resembles the structural format of real
 * credentials for that service (prefix + random hex) but is clearly synthetic.
 *
 * The value is generated with crypto.randomBytes so it is suitable as a
 * placeholder in environments that validate credential format.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const prefix    = KEY_PREFIXES[keyName] ?? DEFAULT_PREFIX;
  // 16 bytes → 32 hex chars gives enough entropy for a placeholder token.
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `${prefix}${randomHex}`;
}

