 * empty it is initialised with an empty array first.
 *
 * @param {object} record  – Fields listed above; must NOT include key values.
 */
function appendRotationLog(record) {
  // Defensive check: refuse to log any field that looks like a key value.
  // A "key value" is anything in a field other than the five allowed fields.
  const ALLOWED_FIELDS = new Set(['timestamp', 'keyName', 'event', 'status', 'error']);
  for (const field of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(field)) {
      throw new Error(
        `key-rotation: attempted to log forbidden field "${field}" – aborting log write`
