/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Safety invariants enforced throughout this module:
 *   - Actual key values are NEVER read into memory beyond what is needed to
 *     locate and replace them inside the file buffer.
 *   - Actual key values are NEVER written to rotation-log.json or to stdout/stderr.
 *   - The .env.test file is updated atomically: written to .env.test.tmp first,
 *     then renamed over the live file so a crash mid-write cannot corrupt it.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module supports rotating ─────────────────────────────────

/**
 * Read .env.test and return every key name whose value looks like an API key
 * that should support rotation.
 *
 * The set of "rotateable" key names is deliberately derived from the live file
 * rather than being hard-coded, so the module stays in sync with .env.test
 * automatically.  We limit discovery to the two names called out in the spec
 * (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY) – other variables in the file are
 * ignored unless you explicitly pass their name to rotateKey().
 *
 * NOTE: this function returns only the *names*; it never surfaces the values.
 *
 * @returns {string[]} List of key names present in .env.test.
 */
function getRotateableKeyNames() {
  const TARGETED_NAMES = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const found = [];

  for (const line of lines) {
    // Skip blank lines and comment lines.
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const name = trimmed.slice(0, eqIdx).trim();
    if (TARGETED_NAMES.has(name)) {
      found.push(name);
    }
  }

  return found;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder value for a rotated key.
 *
 * The placeholder is intentionally NOT a real key – it signals that the slot
 * has been rotated and must be filled with a genuine secret through a secure
 * out-of-band process (e.g. a secrets manager).
 *
 * Format:  ROTATED-<keyName>-<16 random hex bytes>-<ISO timestamp fragment>
 *
 * The random component makes each rotation event unique and auditable without
 * embedding any sensitive material.
 *
 * @param {string} keyName  The environment variable name being rotated.
 * @returns {string}        A non-sensitive placeholder string.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  // Use only the date portion of the ISO string to keep the value short and
  // avoid encoding sub-second timing information that could be correlated.
  const datePart  = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  return `ROTATED-${keyName}-${randomHex}-${datePart}`;
}

// ─── Atomic .env.test writer ──────────────────────────────────────────────────

/**
 * Replace the value of `keyName` inside .env.test with `newPlaceholder`,
 * writing via a tmp file and then atomically renaming into place.
 *
 * If `keyName` is not found in the file the function throws rather than
 * silently succeeding, so callers are forced to handle the error.
 *
 * @param {string} keyName         The environment variable name to update.
 * @param {string} newPlaceholder  The replacement value (never a real secret).
 * @throws {Error} If keyName is not found in .env.test.
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const originalContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = originalContent.split('\n');

  let found = false;
  const updatedLines = lines.map((line) => {
    const trimmed = line.trim();
    // Match lines of the form:   KEY_NAME=<anything>
    // We must check for an exact name match (not a prefix match) to avoid
    // accidentally touching ANTHROPIC_API_KEY_OLD or similar adjacent names.
    if (
      !trimmed.startsWith('#') &&
      trimmed.startsWith(keyName + '=')
    ) {
      found = true;
      // Preserve any leading whitespace the original line had.
      const leadingSpace = line.slice(0, line.length - line.trimStart().length);
      return `${leadingSpace}${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `rotateKey: key "${keyName}" was not found in ${ENV_FILE}. Rotation aborted.`
    );
  }

  const updatedContent = updatedLines.join('\n');

  // Write to tmp first.
  fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });

  // Atomic rename – on POSIX systems rename(2) is guaranteed to be atomic
  // with respect to other processes observing the directory entry.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Audit log writer ─────────────────────────────────────────────────────────

/**
 * Append a rotation event record to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  (ISO 8601, UTC)
 *   - keyName    (the environment variable name, e.g. "ANTHROPIC_API_KEY")
 *   - event      (always "rotated")
 *   - status     ("success" | "failure")
 *   - error      (error message string, only present on failure – never a value)
 *
 * Key values – old or new – are NEVER written here.
 *
 * The log is stored as a JSON array; entries are appended so the full history
 * is preserved across multiple rotations.
 *
 * @param {Object} entry  Log entry object (no key values allowed).
 */
function appendToLog(entry) {
  let records = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8').trim();
      if (raw) {
        records = JSON.parse(raw);
        if (!Array.isArray(records)) {
          // Corrupt log – start fresh rather than crashing.
          records = [];
        }
      }
    } catch {
      // Corrupt log – start fresh rather than crashing.
      records = [];
    }
  }

  records.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(records, null, 2) + '\n', {
    encoding: 'utf8',
    flag: 'w',
  });
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the value of `keyName` in .env.test.
 *
 * Steps:
 *   1. Verify that `keyName` is one of the supported rotateable keys found in
 *      the current .env.test (ANTHROPIC_API_KEY or STRIPE_SECRET_KEY).
 *   2. Generate a random, non-sensitive placeholder value.
 *   3. Atomically update .env.test (write tmp → rename).
 *   4. Append a structured audit record to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }} Rotation metadata (no values).
 * @throws {Error} On validation failure or file I/O error.
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new Error('rotateKey: keyName must be a non-empty string.');
  }

  const timestamp = new Date().toISOString();

  // ── Step 1: validate against the supported set ──────────────────────────
  const supported = getRotateableKeyNames();

  if (!supported.includes(keyName)) {
    const logEntry = {
      timestamp,
      keyName,
      event:  'rotated',
      status: 'failure',
      error:  `Key "${keyName}" is not in the supported rotation set: [${supported.join(', ')}]`,
    };
    appendToLog(logEntry);

    throw new Error(logEntry.error);
  }

  // ── Step 2: generate a placeholder (no real secret material) ────────────
  const placeholder = generatePlaceholder(keyName);

  // ── Step 3: atomically update .env.test ─────────────────────────────────
  try {
    atomicUpdateEnvFile(keyName, placeholder);
  } catch (ioError) {
    const logEntry = {
      timestamp,
      keyName,
      event:  'rotated',
      status: 'failure',
      error:  ioError.message,
    };
    appendToLog(logEntry);

    // Clean up the tmp file if it was left behind by a failed write.
    if (fs.existsSync(ENV_TMP_FILE)) {
      try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* best-effort */ }
    }

    throw ioError;
  }

  // ── Step 4: append success audit record (NO key value logged) ───────────
  const logEntry = {
    timestamp,
    keyName,
    event:  'rotated',
    status: 'success',
  };
  appendToLog(logEntry);

  console.log(
    `[key-rotation] ${timestamp} — "${keyName}" rotated successfully. ` +
    `See ${path.basename(LOG_FILE)} for audit trail.`
  );

  // Return only metadata – never the placeholder or the old value.
  return { keyName, timestamp };
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getRotateableKeyNames,
};

