'use strict';
const fs   = require('fs');
const path = require('path');

// ── helpers ──────────────────────────────────────────────────────────────────
function heading(msg) { console.log('\n\x1b[1m' + msg + '\x1b[0m'); }
function ok(msg)      { console.log('  \x1b[32m✔\x1b[0m ' + msg); }
function fail(msg)    { console.log('  \x1b[31m✖\x1b[0m ' + msg); process.exitCode = 1; }

function assert(cond, msg) { cond ? ok(msg) : fail(msg); }

// Snapshot original .env.test so we can restore it when done.
const ENV_FILE = path.resolve('.env.test');
const LOG_FILE = path.resolve('rotation-log.json');
const originalEnv = fs.readFileSync(ENV_FILE, 'utf8');

// Remove any leftover log file from a previous run.
if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

// ── Test 1: getRotateableKeyNames ────────────────────────────────────────────
heading('Test 1 — getRotateableKeyNames()');
const { rotateKey, getRotateableKeyNames } = require('./key-rotation');

const names = getRotateableKeyNames();
assert(Array.isArray(names),                          'returns an array');
assert(names.includes('ANTHROPIC_API_KEY'),           'finds ANTHROPIC_API_KEY');
assert(names.includes('STRIPE_SECRET_KEY'),           'finds STRIPE_SECRET_KEY');
assert(names.length === 2,                            'finds exactly 2 targeted keys');

// ── Test 2: rotateKey – happy path (ANTHROPIC_API_KEY) ───────────────────────
heading('Test 2 — rotateKey("ANTHROPIC_API_KEY")');

const beforeAnthropicLine = fs.readFileSync(ENV_FILE, 'utf8')
  .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
const oldAnthropicValue = beforeAnthropicLine.split('=')[1];

const result1 = rotateKey('ANTHROPIC_API_KEY');

assert(typeof result1 === 'object',                   'returns an object');
assert(typeof result1.timestamp === 'string',         'result has timestamp');
assert(result1.keyName === 'ANTHROPIC_API_KEY',       'result has correct keyName');
assert(!('value' in result1),                         'result does NOT expose a value field');
assert(!('placeholder' in result1),                   'result does NOT expose placeholder field');

const afterAnthropicLine = fs.readFileSync(ENV_FILE, 'utf8')
  .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
const newAnthropicValue = afterAnthropicLine.split('=')[1];

assert(newAnthropicValue !== oldAnthropicValue,       '.env.test value was changed');
assert(newAnthropicValue.startsWith('ROTATED-ANTHROPIC_API_KEY-'), 'new value has expected prefix');
assert(/^ROTATED-ANTHROPIC_API_KEY-[0-9a-f]{32}-\d{8}$/.test(newAnthropicValue),
                                                      'new value matches placeholder format');

// ── Test 3: rotateKey – happy path (STRIPE_SECRET_KEY) ───────────────────────
heading('Test 3 — rotateKey("STRIPE_SECRET_KEY")');

const result2 = rotateKey('STRIPE_SECRET_KEY');
assert(result2.keyName === 'STRIPE_SECRET_KEY',       'result has correct keyName');
assert(typeof result2.timestamp === 'string',         'result has timestamp');

const afterStripeLine = fs.readFileSync(ENV_FILE, 'utf8')
  .split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
const newStripeValue = afterStripeLine.split('=')[1];

assert(newStripeValue.startsWith('ROTATED-STRIPE_SECRET_KEY-'), 'Stripe placeholder has expected prefix');

// ── Test 4: non-targeted keys are rejected ────────────────────────────────────
heading('Test 4 — unsupported key is rejected');

let threw = false;
try { rotateKey('DATABASE_URL'); } catch (e) {
  threw = true;
  assert(!e.message.includes('postgres://'), 'error message does not leak DB URL');
  assert(e.message.includes('DATABASE_URL'), 'error message names the rejected key');
}
assert(threw, 'throws for a key not in the supported set');

// ── Test 5: atomic write — no tmp file left behind ───────────────────────────
heading('Test 5 — atomic write leaves no tmp file');

assert(!fs.existsSync('.env.test.tmp'), 'no .env.test.tmp after successful rotation');

// ── Test 6: rotation-log.json contents ───────────────────────────────────────
heading('Test 6 — rotation-log.json audit trail');

assert(fs.existsSync(LOG_FILE), 'rotation-log.json was created');

const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
assert(Array.isArray(log), 'log is a JSON array');

// We expect 3 entries: 2 success + 1 failure (DATABASE_URL attempt).
assert(log.length === 3, `log has 3 entries (got ${log.length})`);

const successEntries = log.filter(e => e.status === 'success');
const failureEntries = log.filter(e => e.status === 'failure');

assert(successEntries.length === 2,  '2 success entries');
assert(failureEntries.length === 1,  '1 failure entry');

for (const entry of log) {
  assert('timestamp' in entry,  `entry has timestamp (keyName=${entry.keyName})`);
  assert('keyName'   in entry,  `entry has keyName   (keyName=${entry.keyName})`);
  assert('event'     in entry,  `entry has event     (keyName=${entry.keyName})`);
  assert('status'    in entry,  `entry has status    (keyName=${entry.keyName})`);
}

// ── Test 7: NO key values appear anywhere in the log ─────────────────────────
heading('Test 7 — key values are absent from rotation-log.json');

const logRaw = fs.readFileSync(LOG_FILE, 'utf8');

// Collect every value from the current .env.test to check for leakage.
const envValues = fs.readFileSync(ENV_FILE, 'utf8')
  .split('\n')
  .filter(l => l.trim() && !l.trim().startsWith('#') && l.includes('='))
  .map(l => l.slice(l.indexOf('=') + 1).trim())
  .filter(v => v.length > 4);   // ignore trivially short values

let valueLeak = false;
for (const val of envValues) {
  if (logRaw.includes(val)) {
    fail(`Log contains env value: ${val.slice(0,6)}…`);
    valueLeak = true;
  }
}
if (!valueLeak) ok('No env values found in rotation-log.json');

// Also verify the original canary values (pre-rotation) aren't in the log.
for (const line of originalEnv.split('\n')) {
  if (!line.trim() || line.trim().startsWith('#') || !line.includes('=')) continue;
  const val = line.slice(line.indexOf('=') + 1).trim();
  if (val.length > 4 && logRaw.includes(val)) {
    fail(`Log contains original canary value: ${val.slice(0,6)}…`);
    valueLeak = true;
  }
}
if (!valueLeak) ok('No original canary values found in rotation-log.json');

// ── Test 8: other .env.test variables are untouched ──────────────────────────
heading('Test 8 — non-rotated variables in .env.test are unchanged');

const currentEnv  = fs.readFileSync(ENV_FILE, 'utf8');
const untouched   = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'LOGFIRE_TOKEN'];

for (const key of untouched) {
  const origLine = originalEnv.split('\n').find(l => l.startsWith(key + '='));
  const currLine = currentEnv .split('\n').find(l => l.startsWith(key + '='));
  assert(origLine === currLine, `${key} line is unchanged`);
}

// ── Test 9: repeated rotation produces unique placeholders ───────────────────
heading('Test 9 — repeated rotation yields unique placeholders');

rotateKey('ANTHROPIC_API_KEY');
rotateKey('ANTHROPIC_API_KEY');

const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n').filter(l => l.startsWith('ANTHROPIC_API_KEY='));
// Only the last value matters; uniqueness is guaranteed by the random hex component.
const lastVal = lines[lines.length - 1].split('=')[1];
assert(/^ROTATED-ANTHROPIC_API_KEY-[0-9a-f]{32}-\d{8}$/.test(lastVal),
       'final placeholder still matches expected format');

// ── Cleanup — restore original .env.test and remove log ──────────────────────
heading('Cleanup');
fs.writeFileSync(ENV_FILE, originalEnv, 'utf8');
fs.unlinkSync(LOG_FILE);
ok('.env.test restored to original');
ok('rotation-log.json removed');

console.log('\n' + (process.exitCode ? '\x1b[31mSome tests FAILED.\x1b[0m' : '\x1b[32mAll tests passed.\x1b[0m'));
EOF

