  } catch (ioError) {
    const logEntry = {
      timestamp,
      keyName,
      event:  'rotated',
      status: 'failure',
      error:  ioError.message,
    };
    appendToLog(logEntry);

    // Clean up the tmp file if it was left behind by a failed write.
    if (fs.existsSync(ENV_TMP_FILE)) {
      try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* best-effort */ }
    }

    throw ioError;
  }

  // ── Step 4: append success audit record (NO key value logged) ───────────
  const logEntry = {
    timestamp,
    keyName,
    event:  'rotated',
    status: 'success',
  };
  appendToLog(logEntry);

  console.log(
    `[key-rotation] ${timestamp} — "${keyName}" rotated successfully. ` +
    `See ${path.basename(LOG_FILE)} for audit trail.`
  );

  // Return only metadata – never the placeholder or the old value.
  return { keyName, timestamp };
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getRotateableKeyNames,
};

