assert('LOG: no "ROTATED-" values (only names)',   !logText.includes('ROTATED-ANTHROPIC') && !logText.includes('ROTATED-STRIPE'));
assert('LOG: no "CANARY" credentials',             !logText.includes('CANARY-api-key') && !logText.includes('CANARY-stripe'));
assert('LOG: no actual API key patterns',          !/sk-ant-[^\s"]+/.test(logText));

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── .env.test AFTER all rotations ────────────────────────────');
console.log(fs.readFileSync('.env.test', 'utf8').trimEnd());

console.log('\n── rotation-log.json ────────────────────────────────────────');
console.log(logText);

console.log(`\n═══════════════════════════════════════════`);
console.log(`  Results: ${passed} passed, ${failed} failed`);
console.log(`═══════════════════════════════════════════\n`);
process.exit(failed > 0 ? 1 : 0);
