/**
 * key-rotation.js
 *
 * API key rotation mechanism for managing credential placeholders defined in
 * .env.test. Provides atomic file updates and tamper-evident audit logging.
 *
 * Security guarantees upheld throughout this module:
 *   - Actual key VALUES are never logged, printed, or included in any output.
 *   - Only key NAMES and rotation metadata (timestamps, counters) are recorded.
 *   - The .env.test file is updated atomically via a tmp-file + rename pattern
 *     so a crash mid-write can never leave the file in a corrupt/partial state.
 *   - rotation-log.json is append-only; prior entries are never modified.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that are in scope for rotation ─────────────────────────────────────
// These are determined at runtime by reading .env.test, not hard-coded.

const ROTATEABLE_KEY_NAMES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env-style file into an ordered array of line descriptors so that
 * comments, blank lines, and ordering are all preserved on re-serialisation.
 *
 * Each element is one of:
 *   { type: 'pair',  name: string, value: string, raw: string }
 *   { type: 'other', raw: string }   // comment, blank line, or malformed line
 *
 * @param {string} content  Raw text content of the env file.
 * @returns {Array<object>}
 */
function parseEnvLines(content) {
  return content.split('\n').map(raw => {
    // Match KEY=VALUE lines (value may be quoted or unquoted).
    // We deliberately avoid trimming the raw line so re-serialisation is lossless.
    const match = raw.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      return { type: 'pair', name: match[1], value: match[2], raw };
    }
    return { type: 'other', raw };
  });
}

/**
 * Serialise a parsed line-descriptor array back to env-file text.
 *
 * @param {Array<object>} lines  Output of parseEnvLines (possibly mutated).
 * @returns {string}
 */
function serializeEnvLines(lines) {
  return lines.map(line => {
    if (line.type === 'pair') {
      return `${line.name}=${line.value}`;
    }
    return line.raw;
  }).join('\n');
}

/**
 * Read and parse .env.test, returning the line-descriptor array.
 * Throws a descriptive error if the file cannot be read.
 *
 * @returns {Array<object>}
 */
function readEnvFile() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    return parseEnvLines(content);
  } catch (err) {
    throw new Error(`key-rotation: cannot read env file "${ENV_FILE}": ${err.message}`);
  }
}

/**
 * Atomically write updated content to .env.test by staging it in
 * .env.test.tmp first and then performing an atomic rename.
 *
 * If the rename fails the staging file is cleaned up before re-throwing, so
 * the original .env.test is never left in a partial state.
 *
 * @param {string} content  Full serialised content to write.
 */
function writeEnvFileAtomic(content) {
  try {
    fs.writeFileSync(ENV_TMP_FILE, content, { encoding: 'utf8', mode: 0o600 });
  } catch (err) {
    throw new Error(`key-rotation: cannot write staging file "${ENV_TMP_FILE}": ${err.message}`);
  }

  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Best-effort cleanup of the staging file before surfacing the error.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw new Error(`key-rotation: atomic rename failed: ${err.message}`);
  }
}

/**
 * Generate a new opaque placeholder value for a rotated key.
 *
 * The placeholder is prefixed with "ROTATED-" so it is immediately
 * recognisable as a placeholder (not a real credential), followed by 32
 * cryptographically random hex characters for uniqueness.
 *
 * NOTE: In a production system this function would call the relevant vendor
 * API (Anthropic, Stripe, etc.) to provision a real new key, then return it.
 * Here we produce a clearly-fake placeholder to avoid handling real secrets.
 *
 * @param {string} keyName  The env-variable name (used only as a label).
 * @returns {string}        The new placeholder value.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `PLACEHOLDER-${keyName}-${randomHex}`;
}

/**
 * Read rotation-log.json (or start from an empty array if it does not yet
 * exist) and return the parsed log array.
 *
 * @returns {Array<object>}
 */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) {
    return [];
  }
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      throw new Error('log root is not an array');
    }
    return parsed;
  } catch (err) {
    throw new Error(`key-rotation: cannot read/parse "${LOG_FILE}": ${err.message}`);
  }
}

/**
 * Append a single log entry to rotation-log.json.
 *
 * The entry contains ONLY:
 *   - timestamp   ISO-8601 UTC string
 *   - keyName     The env-variable name that was rotated
 *   - status      "success" or "failure"
 *   - message     Human-readable description (no key values)
 *   - rotationId  Unique ID for this rotation event
 *
 * Key VALUES are explicitly excluded — the function signature does not even
 * accept them.
 *
 * @param {string} keyName  Env-variable name (e.g. "ANTHROPIC_API_KEY").
 * @param {'success'|'failure'} status
 * @param {string} message  Descriptive message safe to store.
 */
function appendLogEntry(keyName, status, message) {
  const entry = {
    rotationId : crypto.randomBytes(8).toString('hex'),
    timestamp  : new Date().toISOString(),
    keyName,          // variable NAME only — never the value
    status,
    message,
  };

  const log = readLog();
  log.push(entry);

  // Write the updated log.  We do NOT use the atomic-rename trick here because
  // the log file is append-only audit data; a crash between writes at most
  // loses the last entry, which is tolerable.  Atomicity matters far more for
  // the credentials file.
  try {
    fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', { encoding: 'utf8', mode: 0o600 });
  } catch (err) {
    // Surface as a warning rather than swallowing; the rotation itself may
    // have succeeded even if logging fails.
    console.warn(`key-rotation: WARNING – could not write log entry to "${LOG_FILE}": ${err.message}`);
  }

  // Echo audit-safe summary to stdout (no values, never the full entry object
  // because that might change in the future — be explicit about what we print).
  console.log(
    `[key-rotation] ${entry.timestamp} | rotationId=${entry.rotationId}` +
    ` | keyName=${entry.keyName} | status=${entry.status} | ${entry.message}`
  );
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Discover which key names are present in .env.test AND are in the
 * ROTATEABLE_KEY_NAMES allow-list.
 *
 * This is the "reads the current variable names from .env.test" step required
 * by the spec; it does not return or expose values.
 *
 * @returns {string[]}  Array of rotateable key names found in the file.
 */
function discoverRotateableKeys() {
  const lines = readEnvFile();
  const foundNames = lines
    .filter(l => l.type === 'pair' && ROTATEABLE_KEY_NAMES.includes(l.name))
    .map(l => l.name);

  console.log(`[key-rotation] Discovered rotateable keys: ${foundNames.join(', ') || '(none)'}`);
  return foundNames;
}

/**
 * Rotate a single key by name.
 *
 * Steps:
 *   1. Verify keyName is in the rotateable allow-list.
 *   2. Verify keyName exists in .env.test.
 *   3. Generate a new placeholder value.
 *   4. Update .env.test atomically (write tmp → rename).
 *   5. Append an audit entry to rotation-log.json (name + metadata only).
 *
 * @param  {string} keyName  The env-variable name to rotate (e.g. "STRIPE_SECRET_KEY").
 * @returns {{ rotationId: string, keyName: string, timestamp: string }}
 *          Rotation metadata (no key values).
 * @throws  {Error}  If keyName is not rotateable, not found, or I/O fails.
 */
function rotateKey(keyName) {
  // ── Validate the requested key name ────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new Error('key-rotation: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEY_NAMES.includes(keyName)) {
    const allowed = ROTATEABLE_KEY_NAMES.join(', ');
    throw new Error(
      `key-rotation: "${keyName}" is not in the rotateable-keys allow-list. ` +
      `Allowed names: ${allowed}`
    );
  }

  // ── Read current env file ───────────────────────────────────────────────────
  let lines;
  try {
    lines = readEnvFile();
  } catch (err) {
    appendLogEntry(keyName, 'failure', `Could not read env file: ${err.message}`);
    throw err;
  }

  const targetLine = lines.find(l => l.type === 'pair' && l.name === keyName);
  if (!targetLine) {
    const msg = `Key "${keyName}" not found in "${ENV_FILE}".`;
    appendLogEntry(keyName, 'failure', msg);
    throw new Error(`key-rotation: ${msg}`);
  }

  // ── Generate replacement placeholder ────────────────────────────────────────
  // generatePlaceholder only receives the KEY NAME — the old value is never
  // passed in and is therefore never accessible within this scope after here.
  const newPlaceholder = generatePlaceholder(keyName);

  // Overwrite only the value portion; do NOT log or return newPlaceholder.
  targetLine.value = newPlaceholder;

  // ── Write updated file atomically ───────────────────────────────────────────
  const updatedContent = serializeEnvLines(lines);
  try {
    writeEnvFileAtomic(updatedContent);
  } catch (err) {
    appendLogEntry(keyName, 'failure', `Atomic write failed: ${err.message}`);
    throw err;
  }

  // ── Audit log (name + metadata only, never the value) ──────────────────────
  const rotationId = crypto.randomBytes(8).toString('hex');

  // Build the log entry directly so we control exactly what is stored.
  const entry = {
    rotationId,
    timestamp : new Date().toISOString(),
    keyName,     // ← variable NAME only
    status    : 'success',
    message   : `Key placeholder rotated successfully.`,
  };

  const log = readLog();
  log.push(entry);
  try {
    fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', { encoding: 'utf8', mode: 0o600 });
  } catch (logErr) {
    console.warn(`key-rotation: WARNING – rotation succeeded but log write failed: ${logErr.message}`);
  }

  console.log(
    `[key-rotation] ${entry.timestamp} | rotationId=${entry.rotationId}` +
    ` | keyName=${entry.keyName} | status=success | Key placeholder rotated successfully.`
  );

  // Return only rotation metadata — the new placeholder value is intentionally
  // NOT included in the return value.
  return {
    rotationId : entry.rotationId,
    keyName    : entry.keyName,
    timestamp  : entry.timestamp,
  };
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = {
  discoverRotateableKeys,
  rotateKey,
  // Exported for testing purposes only:
  _internal: {
    parseEnvLines,
    serializeEnvLines,
    generatePlaceholder,
    readLog,
    ENV_FILE,
    ENV_TMP_FILE,
    LOG_FILE,
    ROTATEABLE_KEY_NAMES,
  },
};

/**
 * key-rotation.test.js
 *
 * Test suite for key-rotation.js.
 * Uses only Node.js built-ins (no external test framework required).
 *
 * Run with:  node key-rotation.test.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Module under test ────────────────────────────────────────────────────────
const {
  discoverRotateableKeys,
  rotateKey,
  _internal: {
    parseEnvLines,
    serializeEnvLines,
    generatePlaceholder,
    readLog,
    ENV_FILE,
    ENV_TMP_FILE,
    LOG_FILE,
    ROTATEABLE_KEY_NAMES,
  },
} = require('./key-rotation');

// ─── Minimal test harness ─────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

function assert(condition, label) {
  if (condition) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.error(`  ✗ ${label}`);
    failed++;
    failures.push(label);
  }
}

function assertThrows(fn, expectedSubstring, label) {
  try {
    fn();
    console.error(`  ✗ ${label}  (expected throw, got none)`);
    failed++;
    failures.push(label);
  } catch (err) {
    if (expectedSubstring && !err.message.includes(expectedSubstring)) {
      console.error(`  ✗ ${label}  (threw "${err.message}", expected to include "${expectedSubstring}")`);
      failed++;
      failures.push(label);
    } else {
      console.log(`  ✓ ${label}`);
      passed++;
    }
  }
}

function section(title) {
  console.log(`\n── ${title} ──`);
}

// ─── Fixture helpers ──────────────────────────────────────────────────────────

const ORIGINAL_ENV = fs.readFileSync(ENV_FILE, 'utf8');
const ORIGINAL_LOG = fs.existsSync(LOG_FILE) ? fs.readFileSync(LOG_FILE, 'utf8') : null;

function restoreEnv() {
  fs.writeFileSync(ENV_FILE, ORIGINAL_ENV, 'utf8');
  // Remove any stale tmp file
  if (fs.existsSync(ENV_TMP_FILE)) fs.unlinkSync(ENV_TMP_FILE);
}

function restoreLog() {
  if (ORIGINAL_LOG === null) {
    if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
  } else {
    fs.writeFileSync(LOG_FILE, ORIGINAL_LOG, 'utf8');
  }
}

function cleanup() {
  restoreEnv();
  restoreLog();
}

// ─── Tests ────────────────────────────────────────────────────────────────────

// ── 1. parseEnvLines ──────────────────────────────────────────────────────────
section('parseEnvLines');

{
  const lines = parseEnvLines('FOO=bar\n# comment\nBAZ=qux\n');
  assert(lines.length === 4, 'parses four elements (3 lines + trailing empty)');
  assert(lines[0].type === 'pair' && lines[0].name === 'FOO' && lines[0].value === 'bar', 'first line is a pair');
  assert(lines[1].type === 'other' && lines[1].raw === '# comment', 'comment preserved as other');
  assert(lines[2].type === 'pair' && lines[2].name === 'BAZ' && lines[2].value === 'qux', 'third line is a pair');
}

{
  const lines = parseEnvLines('KEY=value=with=equals');
