}

// ── 2. serializeEnvLines ──────────────────────────────────────────────────────
section('serializeEnvLines');

{
  const original = '# header\nFOO=bar\nBAZ=qux';
  const lines = parseEnvLines(original);
  const result = serializeEnvLines(lines);
  assert(result === original, 'round-trip produces identical content');
}

{
  const lines = parseEnvLines('KEY=old');
  lines[0].value = 'new';
  assert(serializeEnvLines(lines) === 'KEY=new', 'mutated value is serialised correctly');
}

// ── 3. generatePlaceholder ────────────────────────────────────────────────────
section('generatePlaceholder');

{
  const p1 = generatePlaceholder('ANTHROPIC_API_KEY');
  const p2 = generatePlaceholder('ANTHROPIC_API_KEY');
  assert(p1 !== p2, 'two calls produce distinct placeholders');
  assert(p1.startsWith('PLACEHOLDER-ANTHROPIC_API_KEY-'), 'placeholder contains key name as label');
  assert(!p1.includes('sk-ant'), 'placeholder does not contain real key prefix');
  assert(p1.length > 30, 'placeholder has meaningful length');
}

{
  const p = generatePlaceholder('STRIPE_SECRET_KEY');
  assert(p.startsWith('PLACEHOLDER-STRIPE_SECRET_KEY-'), 'Stripe placeholder labelled correctly');
}

// ── 4. discoverRotateableKeys ─────────────────────────────────────────────────
section('discoverRotateableKeys');

{
  restoreEnv();
  const keys = discoverRotateableKeys();
  assert(keys.includes('ANTHROPIC_API_KEY'), 'discovers ANTHROPIC_API_KEY');
  assert(keys.includes('STRIPE_SECRET_KEY'),  'discovers STRIPE_SECRET_KEY');
  assert(keys.length === 2, 'discovers exactly the two rotateable keys');
}

{
  // Keys not in the allow-list are never returned even if present in the file.
  const keys = discoverRotateableKeys();
  assert(!keys.includes('DATABASE_URL'),          'DATABASE_URL is not in rotateable list');
  assert(!keys.includes('AWS_ACCESS_KEY_ID'),      'AWS_ACCESS_KEY_ID is not in rotateable list');
  assert(!keys.includes('AWS_SECRET_ACCESS_KEY'),  'AWS_SECRET_ACCESS_KEY is not in rotateable list');
  assert(!keys.includes('LOGFIRE_TOKEN'),          'LOGFIRE_TOKEN is not in rotateable list');
}

// ── 5. rotateKey – validation ─────────────────────────────────────────────────
section('rotateKey – input validation');

{
  restoreEnv(); restoreLog();
  assertThrows(() => rotateKey(''), 'non-empty string', 'throws on empty string');
  assertThrows(() => rotateKey(42), 'non-empty string',  'throws on non-string input');
  assertThrows(() => rotateKey('DATABASE_URL'), 'allow-list', 'throws on key not in allow-list');
  assertThrows(() => rotateKey('AWS_SECRET_ACCESS_KEY'), 'allow-list', 'throws on AWS key not in allow-list');
}

// ── 6. rotateKey – successful rotation ───────────────────────────────────────
section('rotateKey – successful rotation of ANTHROPIC_API_KEY');

{
  restoreEnv(); restoreLog();

  const before = fs.readFileSync(ENV_FILE, 'utf8');
  const oldLines = parseEnvLines(before);
  const oldAnthropicLine = oldLines.find(l => l.type === 'pair' && l.name === 'ANTHROPIC_API_KEY');
  const oldValue = oldAnthropicLine.value; // captured ONLY to verify it changed

  const result = rotateKey('ANTHROPIC_API_KEY');

  assert(typeof result === 'object' && result !== null, 'returns an object');
  assert(typeof result.rotationId  === 'string', 'return value has rotationId');
  assert(typeof result.keyName     === 'string', 'return value has keyName');
  assert(typeof result.timestamp   === 'string', 'return value has timestamp');
  assert(result.keyName === 'ANTHROPIC_API_KEY',  'return value keyName matches input');
  assert(!('value' in result),  'return value does NOT expose the new key value');
  assert(!('newValue' in result), 'return value does NOT expose newValue field');
  assert(!('oldValue' in result), 'return value does NOT expose oldValue field');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const newLines = parseEnvLines(after);
  const newAnthropicLine = newLines.find(l => l.type === 'pair' && l.name === 'ANTHROPIC_API_KEY');

  assert(newAnthropicLine !== undefined, 'ANTHROPIC_API_KEY still present in env file after rotation');
  assert(newAnthropicLine.value !== oldValue, 'value has changed after rotation');
  assert(newAnthropicLine.value.startsWith('PLACEHOLDER-'), 'new value is a placeholder');

  // All OTHER keys must be unchanged
  const otherKeyNames = ['DATABASE_URL','AWS_ACCESS_KEY_ID','AWS_SECRET_ACCESS_KEY','STRIPE_SECRET_KEY','LOGFIRE_TOKEN'];
  for (const name of otherKeyNames) {
    const oldLine = oldLines.find(l => l.type === 'pair' && l.name === name);
    const newLine = newLines.find(l => l.type === 'pair' && l.name === name);
    assert(newLine && oldLine && newLine.value === oldLine.value, `non-rotated key ${name} is unchanged`);
  }

  // Comments and structure preserved
  assert(after.includes('# Synthetic test credentials'), 'comment line preserved after rotation');
}

// ── 7. rotateKey – successful rotation of STRIPE_SECRET_KEY ──────────────────
section('rotateKey – successful rotation of STRIPE_SECRET_KEY');

{
  restoreEnv(); restoreLog();

  const result = rotateKey('STRIPE_SECRET_KEY');
  assert(result.keyName === 'STRIPE_SECRET_KEY', 'keyName is STRIPE_SECRET_KEY');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const newLines = parseEnvLines(after);
  const stripeLine = newLines.find(l => l.type === 'pair' && l.name === 'STRIPE_SECRET_KEY');

  assert(stripeLine !== undefined, 'STRIPE_SECRET_KEY still present after rotation');
  assert(stripeLine.value.startsWith('PLACEHOLDER-STRIPE_SECRET_KEY-'), 'new Stripe value is labelled placeholder');
}

