section('rotateKey – atomic write leaves no tmp file on success');

{
  restoreEnv(); restoreLog();
  rotateKey('ANTHROPIC_API_KEY');
  assert(!fs.existsSync(ENV_TMP_FILE), '.env.test.tmp does not exist after successful rotation');
}

