section('rotateKey – audit log correctness');

{
  restoreEnv(); restoreLog();

  const result = rotateKey('ANTHROPIC_API_KEY');
  const log = readLog();

  assert(Array.isArray(log),  'rotation-log.json is an array');
  assert(log.length >= 1,     'log has at least one entry');

  const entry = log[log.length - 1];
