  assert(typeof entry.timestamp  === 'string',  'log entry has timestamp');
  assert(entry.keyName === 'ANTHROPIC_API_KEY', 'log entry keyName matches rotated key');
  assert(entry.status  === 'success',           'log entry status is success');
  assert(typeof entry.message === 'string',     'log entry has message string');

