  const logRaw = fs.readFileSync(LOG_FILE, 'utf8');
  assert(!logRaw.includes('sk-ant'),   'log does NOT contain Anthropic key prefix');
  assert(!logRaw.includes('sk_live'),  'log does NOT contain Stripe key prefix');
  assert(!logRaw.includes('CANARY'),   'log does NOT contain CANARY sentinel value');
  assert(!logRaw.includes('PLACEHOLDER-ANTHROPIC_API_KEY'), 'log does NOT contain actual new placeholder value');
  assert(!('value'    in entry), 'log entry has no "value" field');
  assert(!('newValue' in entry), 'log entry has no "newValue" field');
  assert(!('oldValue' in entry), 'log entry has no "oldValue" field');
}

// ── 10. Audit log – multiple rotations accumulate entries ─────────────────────
section('rotateKey – multiple rotations accumulate log entries');

{
  restoreEnv(); restoreLog();

  rotateKey('ANTHROPIC_API_KEY');
  restoreEnv(); // restore so second rotation has a valid file
  rotateKey('STRIPE_SECRET_KEY');

  const log = readLog();
  assert(log.length === 2, 'log has exactly two entries after two rotations');

  const ids = log.map(e => e.rotationId);
  assert(new Set(ids).size === ids.length, 'each log entry has a unique rotationId');
}

// ── 11. rotateKey – two successive rotations change value each time ───────────
section('rotateKey – successive rotations produce distinct new values');

{
  restoreEnv(); restoreLog();

  rotateKey('ANTHROPIC_API_KEY');
  const after1 = parseEnvLines(fs.readFileSync(ENV_FILE, 'utf8'))
    .find(l => l.type === 'pair' && l.name === 'ANTHROPIC_API_KEY').value;

  rotateKey('ANTHROPIC_API_KEY');
  const after2 = parseEnvLines(fs.readFileSync(ENV_FILE, 'utf8'))
    .find(l => l.type === 'pair' && l.name === 'ANTHROPIC_API_KEY').value;

  assert(after1 !== after2, 'second rotation produces a different value than the first');
}

// ── 12. Return value never contains secret data ───────────────────────────────
section('rotateKey – return value is safe');

{
  restoreEnv(); restoreLog();
  const result = rotateKey('STRIPE_SECRET_KEY');
  const serialised = JSON.stringify(result);

  assert(!serialised.includes('sk_live'),  'return value JSON does not contain Stripe key prefix');
  assert(!serialised.includes('CANARY'),   'return value JSON does not contain CANARY sentinel');
  assert(!serialised.includes('PLACEHOLDER'), 'return value JSON does not contain the new placeholder value');
  assert(Object.keys(result).sort().join(',') === 'keyName,rotationId,timestamp',
