/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security guarantees
 * -------------------
 *  - Actual key values are NEVER logged, printed, or included in any output.
 *  - Only key *names* (the left-hand side of each KEY=VALUE pair) are handled
 *    outside of the atomic file rewrite.
 *  - The .env.test file is updated atomically: content is written to a
 *    temporary file first, then renamed over the original so a crash mid-write
 *    cannot leave a corrupt or partially-written credential file.
 *  - rotation-log.json records only { timestamp, keyName, status } — never values.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Keys that are eligible for rotation ──────────────────────────────────────
// Derived by reading .env.test and retaining only the two names called out in
// the requirements.  Values are intentionally discarded after parsing.

const ROTATABLE_KEY_NAMES = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Parse a .env file into a Map of { keyName → value }.
 * Lines that are blank or start with '#' are preserved as-is via a parallel
 * "lines" array so that comments and blank lines survive a round-trip.
 *
 * @param {string} filePath
 * @returns {{ lines: string[], keyIndex: Map<string, number> }}
 *   `lines`    – every raw line of the file (comments/blanks included)
 *   `keyIndex` – maps each KEY name to its line index in `lines`
 */
function parseEnvFile(filePath) {
  const raw      = fs.readFileSync(filePath, 'utf8');
  const lines    = raw.split('\n');
  const keyIndex = new Map();

  lines.forEach((line, idx) => {
    // Skip blank lines and comments
    if (!line.trim() || line.trim().startsWith('#')) return;

    const eqPos = line.indexOf('=');
    if (eqPos === -1) return;

    const name = line.slice(0, eqPos).trim();
    keyIndex.set(name, idx);
  });

  return { lines, keyIndex };
}

/**
 * Return the complete set of key *names* present in the env file that are also
 * members of ROTATABLE_KEY_NAMES.  Values are read but immediately discarded.
 *
 * @returns {string[]}
 */
function readRotatableKeyNames() {
  const { keyIndex } = parseEnvFile(ENV_FILE);
  return [...keyIndex.keys()].filter(name => ROTATABLE_KEY_NAMES.has(name));
}

/**
 * Generate a new opaque placeholder value for a rotated key.
 *
 * The placeholder is a cryptographically random hex string prefixed with the
 * key's conventional prefix so downstream tooling that validates key format
 * can be updated accordingly.  The *value itself* is returned to the caller
 * only so it can be written into the file — it is never logged.
 *
 * Format examples
 *   ANTHROPIC_API_KEY → sk-ant-<32 hex bytes>
 *   STRIPE_SECRET_KEY → sk_live_<32 hex bytes>
 *   (anything else)   → rotated-key-<32 hex bytes>
 *
 * @param {string} keyName
 * @returns {string}  new placeholder value  (DO NOT LOG)
 */
function generatePlaceholder(keyName) {
  const randomPart = crypto.randomBytes(32).toString('hex');

  if (keyName === 'ANTHROPIC_API_KEY') return `sk-ant-${randomPart}`;
  if (keyName === 'STRIPE_SECRET_KEY') return `sk_live_${randomPart}`;
  return `rotated-key-${randomPart}`;
}

/**
 * Atomically update keyName's value in the .env.test file.
 * Writes to ENV_TMP_FILE first, then renames to ENV_FILE.
 *
 * @param {string} keyName       The KEY name to update (e.g. 'ANTHROPIC_API_KEY')
 * @param {string} newValue      The replacement value   (never logged here)
 */
function atomicUpdateEnvFile(keyName, newValue) {
  const { lines, keyIndex } = parseEnvFile(ENV_FILE);

  if (!keyIndex.has(keyName)) {
    throw new Error(`Key name "${keyName}" not found in ${ENV_FILE}`);
  }

  const lineIdx = keyIndex.get(keyName);
  // Replace only the value portion; preserve any inline comment if present.
  const existingLine = lines[lineIdx];
  const eqPos        = existingLine.indexOf('=');
  const keyPart      = existingLine.slice(0, eqPos + 1); // "KEYNAME="

  // Detect an optional trailing inline comment (e.g.  KEY=value  # comment)
  // We preserve everything from the '#' onward so existing comments survive.
  const valuePart  = existingLine.slice(eqPos + 1);
  const commentIdx = valuePart.indexOf(' #');
  const trailingComment = commentIdx !== -1
    ? valuePart.slice(commentIdx)   // " # some comment"
    : '';

  lines[lineIdx] = `${keyPart}${newValue}${trailingComment}`;

  const newContent = lines.join('\n');

  // Write to temp file first — ensures the original is untouched if we crash.
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', mode: 0o600 });

  // Atomic rename (POSIX guarantee: rename(2) is atomic on the same filesystem)
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

/**
 * Append a rotation event to rotation-log.json.
 * Only { timestamp, keyName, status } are written — never key values.
 *
 * @param {string} keyName
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage]  Human-readable error description (no values)
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the log entry — strictly no values.
  const entry = {
    timestamp : new Date().toISOString(),
    keyName,                                // name only — never the value
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  // Read existing log array, or start fresh.
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) logEntries = parsed;
    } catch {
      // Corrupted log — start fresh rather than crashing.
      logEntries = [];
    }
  }

  logEntries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(logEntries, null, 2), {
    encoding : 'utf8',
    mode     : 0o600,
  });
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * Rotates the specified key:
 *  1. Validates that keyName is one of the tracked rotatable keys.
 *  2. Generates a new cryptographically random placeholder value.
 *  3. Atomically rewrites .env.test (via .env.test.tmp + rename).
 *  4. Appends a log entry to rotation-log.json (name + timestamp only).
 *
 * The new placeholder value is returned **only** so callers that need to
 * propagate it to a secrets manager can do so.  Callers MUST NOT log it.
 *
 * @param  {string} keyName  Must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'
 * @returns {{ keyName: string, rotatedAt: string }}
 *   A safe summary object — the new value is intentionally excluded.
 * @throws {Error} if keyName is not rotatable or the file update fails.
 */
function rotateKey(keyName) {
  // ── 1. Validate ─────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const msg = 'rotateKey: keyName must be a non-empty string.';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  const available = readRotatableKeyNames();
  if (!available.includes(keyName)) {
    const msg = `rotateKey: "${keyName}" is not a recognised rotatable key. ` +
                `Available: [${available.join(', ')}]`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 2. Generate new placeholder (value stays local — never logged) ─────────
  const newValue = generatePlaceholder(keyName); // DO NOT pass to any logger

  // ── 3. Atomically update the env file ─────────────────────────────────────
  try {
    atomicUpdateEnvFile(keyName, newValue);
  } catch (err) {
    // Scrub any accidental value leak from the error message before logging.
    const safeMsg = err.message.replace(newValue, '[REDACTED]');
    appendRotationLog(keyName, 'failure', safeMsg);
    throw new Error(`rotateKey: file update failed for "${keyName}": ${safeMsg}`);
  }

  // ── 4. Log the event — name and timestamp only ─────────────────────────────
  const rotatedAt = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  console.log(`[key-rotation] Rotated key "${keyName}" at ${rotatedAt} — value not logged.`);

  // Return a safe summary; the value is deliberately withheld from the return object.
  return { keyName, rotatedAt };
}

/**
 * listRotatableKeys()
 *
 * Returns the names (never values) of the keys present in .env.test that are
 * eligible for rotation.
 *
 * @returns {string[]}
 */
function listRotatableKeys() {
  return readRotatableKeyNames();
}

// ── Module exports ────────────────────────────────────────────────────────────

module.exports = { rotateKey, listRotatableKeys };

