/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security contract
 * -----------------
 *  • Reads .env.test to discover which key NAMES need rotation support.
 *  • Only the two explicitly managed keys (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY)
 *    are eligible for rotation; all other variables are preserved verbatim.
 *  • Generates a placeholder value for the rotated key; the placeholder is a
 *    structurally-valid stand-in (prefixed, random hex) that is safe to store.
 *  • Writes the updated file atomically: .env.test.tmp → .env.test (rename).
 *  • Logs ONLY the key name and a timestamp to rotation-log.json.
 *    Key values (old or new) are NEVER logged, printed, or returned to callers.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys eligible for rotation ───────────────────────────────────────────────

/**
 * The set of key names this module is permitted to rotate.
 * Populated at startup by reading the names that are present in .env.test.
 * Only names that also appear in MANAGED_KEY_PREFIXES are included.
 */
const MANAGED_KEY_PREFIXES = {
  ANTHROPIC_API_KEY:  'sk-ant-',
  STRIPE_SECRET_KEY:  'sk_live_',
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of entries so that lines that are
 * comments, blanks, or unknown assignments are preserved exactly.
 *
 * Each entry is one of:
 *   { type: 'assignment', key: string, raw: string }   — KEY=VALUE line
 *   { type: 'other',      raw: string }                — comment / blank
 *
 * @param {string} filePath
 * @returns {{ entries: Array, keys: Set<string> }}
 */
function parseEnvFile(filePath) {
  const text    = fs.readFileSync(filePath, 'utf8');
  const lines   = text.split('\n');
  const entries = [];
  const keys    = new Set();

  for (const line of lines) {
    // Match KEY=VALUE (optional spaces around '=', key is UPPER_SNAKE_CASE)
    const match = line.match(/^([A-Z][A-Z0-9_]*)=(.*)/);
    if (match) {
      const key = match[1];
      entries.push({ type: 'assignment', key, raw: line });
      keys.add(key);
    } else {
      entries.push({ type: 'other', raw: line });
    }
  }

  return { entries, keys };
}

/**
 * Serialise the entries array back to a .env-formatted string.
 *
 * @param {Array} entries
 * @returns {string}
 */
function serialiseEntries(entries) {
  return entries.map(e => e.raw).join('\n');
}

/**
 * Generate a new placeholder value for the given key name.
 * The placeholder uses the key's known prefix so it remains structurally
 * recognisable, followed by 32 random hex characters.
 * The actual value is never logged or returned to external callers.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const prefix    = MANAGED_KEY_PREFIXES[keyName] ?? 'key-';
  const randomHex = crypto.randomBytes(16).toString('hex');   // 32 hex chars
  return `${prefix}${randomHex}`;
}

/**
 * Append one rotation event to rotation-log.json.
 * Only the key NAME and timestamp are written — never the value.
 *
 * @param {string} keyName
 */
function appendRotationLog(keyName) {
  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // If the file is malformed start fresh; don't propagate parse errors.
      log = [];
    }
  }

  log.push({
    timestamp: new Date().toISOString(),
    keyName,                        // ← key name only; value is intentionally absent
    status: 'rotated',
  });

  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Return the set of key names read from .env.test that are also in the
 * managed list.  Callers can use this to know which keys support rotation
 * without ever touching a value.
 *
 * @returns {Set<string>}
 */
function getManagedKeys() {
  const { keys } = parseEnvFile(ENV_FILE);
  const managed  = new Set();
  for (const name of Object.keys(MANAGED_KEY_PREFIXES)) {
    if (keys.has(name)) {
      managed.add(name);
    }
  }
  return managed;
}

/**
 * Rotate the specified key in .env.test.
 *
 * Steps:
 *  1. Verify the key name is in the managed set (guards against arbitrary
 *     variable writes).
 *  2. Parse the current .env.test.
 *  3. Generate a new placeholder value (never exposed to callers).
 *  4. Rebuild the file contents with the single line replaced.
 *  5. Write atomically: .env.test.tmp → .env.test (rename).
 *  6. Log the rotation event (name + timestamp only) to rotation-log.json.
 *
 * @param {string} keyName  - Must be one of the managed key names.
 * @throws {Error}          - If keyName is not managed or file I/O fails.
 */
function rotateKey(keyName) {
  // ── 1. Guard: only managed keys may be rotated ──────────────────────────────
  const managed = getManagedKeys();
  if (!managed.has(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" is not a managed key eligible for rotation. ` +
      `Eligible keys: ${[...managed].join(', ')}`
    );
  }

  // ── 2. Parse current env file ────────────────────────────────────────────────
  const { entries } = parseEnvFile(ENV_FILE);

  // ── 3. Generate new placeholder (value stays local; never returned/logged) ───
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 4. Rebuild entries with the target line replaced ─────────────────────────
  let replaced = false;
  const updatedEntries = entries.map(entry => {
    if (entry.type === 'assignment' && entry.key === keyName) {
      replaced = true;
      // Reconstruct the raw line with the new placeholder value
      return { ...entry, raw: `${keyName}=${newPlaceholder}` };
    }
    return entry;
  });

  if (!replaced) {
    // Should not happen given the managed-key guard, but be explicit.
    throw new Error(`rotateKey: key "${keyName}" was not found in ${ENV_FILE}`);
  }

  // ── 5. Atomic write: tmp file → rename ───────────────────────────────────────
  const newContent = serialiseEntries(updatedEntries);
  fs.writeFileSync(ENV_TMP_FILE, newContent, 'utf8');
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);   // atomic on POSIX; best-effort on Windows

  // ── 6. Audit log (key name + timestamp only) ─────────────────────────────────
  appendRotationLog(keyName);

  // Intentionally return nothing — callers have no need for the new value.
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, getManagedKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses only Node built-ins (no test framework dependency).
 *
 * Run with:  node key-rotation.test.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE       = path.resolve(__dirname, '.env.test');
const ENV_BACKUP     = path.resolve(__dirname, '.env.test.bak');
const ENV_TMP        = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE       = path.resolve(__dirname, 'rotation-log.json');
const LOG_BACKUP     = path.resolve(__dirname, 'rotation-log.json.bak');

// ─── Minimal test harness ────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
  }
}

// ─── Setup / teardown helpers ────────────────────────────────────────────────

const ORIGINAL_ENV_CONTENT = fs.readFileSync(ENV_FILE, 'utf8');

function backupFiles() {
  fs.writeFileSync(ENV_BACKUP, fs.readFileSync(ENV_FILE, 'utf8'), 'utf8');
  if (fs.existsSync(LOG_FILE)) {
    fs.writeFileSync(LOG_BACKUP, fs.readFileSync(LOG_FILE, 'utf8'), 'utf8');
  }
}

function restoreFiles() {
  fs.writeFileSync(ENV_FILE, fs.readFileSync(ENV_BACKUP, 'utf8'), 'utf8');
  fs.unlinkSync(ENV_BACKUP);

  if (fs.existsSync(LOG_BACKUP)) {
    fs.writeFileSync(LOG_FILE, fs.readFileSync(LOG_BACKUP, 'utf8'), 'utf8');
    fs.unlinkSync(LOG_BACKUP);
  } else if (fs.existsSync(LOG_FILE)) {
    fs.unlinkSync(LOG_FILE);
  }

  // Remove stray tmp file if any
  if (fs.existsSync(ENV_TMP)) fs.unlinkSync(ENV_TMP);
}

// ─── Helper: fresh require (bypass module cache) ──────────────────────────────

function freshRequire(mod) {
  delete require.cache[require.resolve(mod)];
  return require(mod);
}

// ─── Tests ───────────────────────────────────────────────────────────────────

(async () => {
  console.log('\nkey-rotation.js — test suite\n');

  // ── getManagedKeys ───────────────────────────────────────────────────────────

  console.log('getManagedKeys()');

  await test('returns a Set', () => {
    const { getManagedKeys } = freshRequire('./key-rotation');
    const result = getManagedKeys();
    assert(result instanceof Set, 'result should be a Set');
  });

  await test('contains ANTHROPIC_API_KEY', () => {
    const { getManagedKeys } = freshRequire('./key-rotation');
    assert(getManagedKeys().has('ANTHROPIC_API_KEY'), 'should contain ANTHROPIC_API_KEY');
  });

  await test('contains STRIPE_SECRET_KEY', () => {
    const { getManagedKeys } = freshRequire('./key-rotation');
    assert(getManagedKeys().has('STRIPE_SECRET_KEY'), 'should contain STRIPE_SECRET_KEY');
  });

  await test('does NOT contain unmanaged keys (e.g. DATABASE_URL)', () => {
    const { getManagedKeys } = freshRequire('./key-rotation');
    assert(!getManagedKeys().has('DATABASE_URL'), 'DATABASE_URL should not be managed');
  });

  // ── rotateKey — guard / validation ──────────────────────────────────────────

  console.log('\nrotateKey() — validation');

  await test('throws for an unrecognised key name', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      let threw = false;
