  await test('creates rotation-log.json if it does not exist', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');
      assert(fs.existsSync(LOG_FILE), 'rotation-log.json should be created');
    } finally {
      restoreFiles();
    }
  });

  await test('log entry contains timestamp in ISO 8601 format', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');

      const log   = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
      const entry = log[log.length - 1];
      assert(entry.timestamp, 'entry should have a timestamp');
      assert(!isNaN(Date.parse(entry.timestamp)), 'timestamp should be a valid date');
    } finally {
      restoreFiles();
    }
  });

  await test('log entry contains the key name', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');

      const log   = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
      const entry = log[log.length - 1];
      assert(entry.keyName === 'ANTHROPIC_API_KEY', 'keyName should be ANTHROPIC_API_KEY');
    } finally {
      restoreFiles();
    }
  });

  await test('log entry contains status "rotated"', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');

      const log   = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
      const entry = log[log.length - 1];
      assert(entry.status === 'rotated', 'status should be "rotated"');
    } finally {
      restoreFiles();
    }
  });

  await test('log entry does NOT contain any key value', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');

      const raw   = fs.readFileSync(LOG_FILE, 'utf8');
      const entry = JSON.parse(raw)[0];

      // The entry object must not have a "value", "key", "secret", or similar field
      const forbidden = ['value', 'keyValue', 'secret', 'newValue', 'oldValue', 'key'];
      for (const field of forbidden) {
        assert(!(field in entry), `log entry must not contain field "${field}"`);
      }
      // Also verify the raw JSON doesn't contain any of the actual key values from the env
      const envContent = ORIGINAL_ENV_CONTENT;
      const values = envContent.split('\n')
        .filter(l => l.startsWith('ANTHROPIC_API_KEY=') || l.startsWith('STRIPE_SECRET_KEY='))
        .map(l => l.split('=').slice(1).join('=').trim());

      for (const v of values) {
        assert(!raw.includes(v), `log file must not contain actual key values`);
      }
    } finally {
      restoreFiles();
    }
  });

  await test('accumulates multiple log entries across rotations', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');
      rotateKey('STRIPE_SECRET_KEY');
      rotateKey('ANTHROPIC_API_KEY');

      const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
      assert(log.length === 3, `expected 3 log entries, got ${log.length}`);
    } finally {
      restoreFiles();
    }
  });

  await test('each successive rotation produces a different placeholder value', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');
      const after1 = fs.readFileSync(ENV_FILE, 'utf8')
        .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));

      rotateKey('ANTHROPIC_API_KEY');
      const after2 = fs.readFileSync(ENV_FILE, 'utf8')
        .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));

      assert(after1 !== after2, 'each rotation should produce a unique placeholder');
    } finally {
      restoreFiles();
    }
  });

  await test('rotateKey() returns undefined (does not leak new value)', () => {
    backupFiles();
    try {
      const { rotateKey } = freshRequire('./key-rotation');
      const result = rotateKey('ANTHROPIC_API_KEY');
      assert(result === undefined, `rotateKey should return undefined, got: ${typeof result}`);
    } finally {
      restoreFiles();
    }
  });

  // ── Summary ──────────────────────────────────────────────────────────────────

  console.log(`\n${'─'.repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed`);
  if (failed > 0) {
    process.exit(1);
  }
})();

