/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security design principles enforced throughout:
 *  - Actual key VALUES are never read into application memory beyond what is
 *    strictly required to locate the correct line in the env file.
 *  - Key values are NEVER stored, logged, returned, or transmitted.
 *  - Only the key NAME (variable name) and rotation metadata (timestamp,
 *    success/failure) are written to the audit log.
 *  - The .env.test file is updated atomically: the new content is first
 *    written to a temp file (.env.test.tmp) and then renamed over the
 *    original, so a crash mid-write never leaves a partial or empty file.
 *  - The temp file is always cleaned up, even on error.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is permitted to rotate ────────────────────────────
// Derived by reading only the variable *names* from .env.test at startup.

/**
 * Parses .env.test and returns the list of key *names* (not values) that
 * are eligible for rotation.
 *
 * The set of rotateable keys is intentionally restricted to the two names
 * called out in the requirements: ANTHROPIC_API_KEY and STRIPE_SECRET_KEY.
 * Any other variables present in .env.test are ignored and left untouched.
 *
 * @returns {string[]} Array of eligible key names found in .env.test.
 */
function getRotateableKeyNames() {
  const ALLOWED_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const rawLines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');

  const found = [];
  for (const line of rawLines) {
    // Skip comments and blank lines
    if (!line.trim() || line.trim().startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const varName = line.slice(0, eqIndex).trim();
    if (ALLOWED_KEYS.has(varName)) {
      found.push(varName);
    }
  }

  return found;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generates a cryptographically random placeholder value for a rotated key.
 *
 * Format:  ROTATED-<keyName>-<hex32>
 *
 * The placeholder is explicitly NOT a real credential; it signals that an
 * actual secret must be injected by the secrets-management system before the
 * application is started.
 *
 * @param {string} keyName  The variable name being rotated (used as a label).
 * @returns {string}        A random, non-secret placeholder string.
 */
function generatePlaceholder(keyName) {
  // 16 random bytes → 32 hex characters; enough entropy to be unique per rotation
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${randomHex}`;
}

// ─── Atomic .env.test writer ──────────────────────────────────────────────────

/**
 * Replaces the value of `keyName` in .env.test with `newPlaceholder`,
 * writing atomically via a temp-file + rename strategy.
 *
 * Only the single target line is modified; all other lines (including other
 * secrets) are copied verbatim without ever being inspected by this code.
 *
 * @param {string} keyName         The variable name whose value will change.
 * @param {string} newPlaceholder  The replacement value (a placeholder, not a
 *                                 real secret).
 * @throws {Error} If keyName is not found in .env.test.
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const rawContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = rawContent.split('\n');

  let keyFound = false;

  const updatedLines = lines.map((line) => {
    // Skip comments and blanks without touching them
    if (!line.trim() || line.trim().startsWith('#')) return line;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) return line;

    const varName = line.slice(0, eqIndex).trim();
    if (varName === keyName) {
      keyFound = true;
      // Replace only the value portion; the variable name is preserved exactly.
      // IMPORTANT: we do NOT log, inspect, or store the old value.
      return `${varName}=${newPlaceholder}`;
    }

    // All other lines are passed through as-is (values never read/logged).
    return line;
  });

  if (!keyFound) {
    throw new Error(
      `rotateKey: key "${keyName}" not found in ${ENV_FILE}. ` +
      'Cannot perform rotation.'
    );
  }

  const newContent = updatedLines.join('\n');

  // ── Atomic write ──────────────────────────────────────────────────────────
  // 1. Write to a temp file (crash here → original file untouched).
  // 2. fsync the temp file so data is on disk before rename.
  // 3. rename() is atomic on POSIX: readers always see either the old or the
  //    new complete file, never a partial one.
  try {
    const fd = fs.openSync(ENV_TMP_FILE, 'w', 0o600); // owner-read/write only
    try {
      fs.writeSync(fd, newContent, 0, 'utf8');
      fs.fsyncSync(fd);           // flush kernel buffers → disk
    } finally {
      fs.closeSync(fd);
    }

    fs.renameSync(ENV_TMP_FILE, ENV_FILE); // atomic swap
  } catch (writeErr) {
    // Best-effort cleanup of the temp file so it does not linger.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw writeErr;
  }
}

// ─── Audit logger ─────────────────────────────────────────────────────────────

/**
 * Appends a rotation event to rotation-log.json.
 *
 * The log entry records:
 *   - timestamp  (ISO-8601 UTC)
 *   - keyName    (variable name only — NEVER the value)
 *   - status     ("success" | "failure")
 *   - error      (error message string, only present on failure)
 *
 * If rotation-log.json does not yet exist it is created with an empty array.
 *
 * @param {string}      keyName   Variable name that was rotated.
 * @param {'success'|'failure'} status
 * @param {Error|null}  [err]     Error object when status === 'failure'.
 */
function appendRotationLog(keyName, status, err = null) {
  // Build the log entry — key values are intentionally absent.
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,                        // variable name only, never the value
    status,
    ...(err ? { error: err.message } : {}),
  };

  // Read existing log array (or start fresh).
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
    } catch (_parseErr) {
      // Corrupted log — start over rather than crash the rotation process.
      logEntries = [];
    }
  }

  logEntries.push(entry);

  // Write the updated log.  We accept that this write is not atomic (the log
  // is append-only audit data; a torn write is recoverable from the prior
  // entries and does not affect the env file).
  fs.writeFileSync(LOG_FILE, JSON.stringify(logEntries, null, 2) + '\n', {
    encoding: 'utf8',
    mode: 0o600,   // owner-read/write — log must not be world-readable
  });

  // Echo a human-readable summary to stdout (key value is never included).
  const prefix = status === 'success' ? '✔' : '✖';
  console.log(
    `[key-rotation] ${prefix} ${entry.timestamp} | key: ${keyName} | status: ${status}` +
    (err ? ` | error: ${err.message}` : '')
  );
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotates the env-file entry for `keyName`.
 *
 * Steps:
 *  1. Validates that `keyName` is one of the rotateable keys declared in
 *     .env.test (ANTHROPIC_API_KEY or STRIPE_SECRET_KEY).
 *  2. Generates a random placeholder value (not a real secret).
 *  3. Atomically rewrites .env.test with the placeholder in place of the
 *     existing value (which is never read or logged).
 *  4. Appends an audit entry to rotation-log.json (name + timestamp only).
 *
 * @param {string} keyName  The env variable name to rotate, e.g.
 *                          'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the rotation — the new placeholder is NOT returned.
 * @throws {Error} On invalid keyName or file-system failure.
 */
function rotateKey(keyName) {
  // ── 1. Input validation ──────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const err = new Error('rotateKey: keyName must be a non-empty string.');
    appendRotationLog(String(keyName), 'failure', err);
    throw err;
  }

  const rotateable = getRotateableKeyNames();

  if (!rotateable.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not a rotateable key. ` +
      `Eligible keys found in .env.test: [${rotateable.join(', ')}].`
    );
    appendRotationLog(keyName, 'failure', err);
    throw err;
  }

  // ── 2. Generate placeholder ──────────────────────────────────────────────
  // The placeholder is produced locally and used exactly once.
  // It is written directly into atomicUpdateEnvFile and then discarded —
  // it is never stored in a variable that persists beyond this call frame,
  // logged, or returned to the caller.
  const placeholder = generatePlaceholder(keyName);

  // ── 3. Atomic file update ────────────────────────────────────────────────
  try {
    atomicUpdateEnvFile(keyName, placeholder);
  } catch (fileErr) {
    appendRotationLog(keyName, 'failure', fileErr);
    throw fileErr;
  }

  // ── 4. Audit log ─────────────────────────────────────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  // Return only metadata — the placeholder itself is NOT included.
  return { keyName, timestamp };
}

/**
 * Returns the list of key names (not values) that are eligible for rotation,
 * as read from .env.test.
 *
 * Safe to expose: contains only variable names, never values.
 *
 * @returns {string[]}
 */
function listRotateableKeys() {
  return getRotateableKeyNames();
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, listRotateableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Verifies correctness, atomicity guarantees, and — critically — that
 * no actual key values appear anywhere in the log or in return values.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Paths mirrored from the module under test ────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Minimal test harness (no external deps) ─────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) {
    console.error(`  ✖ FAIL: ${message}`);
    failed++;
  } else {
    console.log(`  ✔ PASS: ${message}`);
    passed++;
  }
}

function assertThrows(fn, expectedMessageFragment, label) {
  try {
    fn();
    console.error(`  ✖ FAIL: ${label} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (err.message.includes(expectedMessageFragment)) {
      console.log(`  ✔ PASS: ${label}`);
      passed++;
    } else {
      console.error(
        `  ✖ FAIL: ${label} — wrong error message.\n` +
        `         expected to contain: "${expectedMessageFragment}"\n` +
        `         actual: "${err.message}"`
      );
      failed++;
    }
  }
}

// ─── Fixture helpers ─────────────────────────────────────────────────────────

const ORIGINAL_ENV = fs.readFileSync(ENV_FILE, 'utf8');

/** Restore .env.test and remove artefacts between tests. */
function resetFixtures() {
  fs.writeFileSync(ENV_FILE, ORIGINAL_ENV, { encoding: 'utf8', mode: 0o600 });
  if (fs.existsSync(LOG_FILE))     fs.unlinkSync(LOG_FILE);
  if (fs.existsSync(ENV_TMP_FILE)) fs.unlinkSync(ENV_TMP_FILE);
  // Bust the require cache so the module re-reads .env.test fresh each suite.
  delete require.cache[require.resolve('./key-rotation')];
}

// ─── Test suites ─────────────────────────────────────────────────────────────

console.log('\n══════════════════════════════════════════════');
console.log(' key-rotation.js — test suite');
console.log('══════════════════════════════════════════════\n');

// ── Suite 1: listRotateableKeys ───────────────────────────────────────────────
console.log('Suite 1: listRotateableKeys()');
{
  resetFixtures();
  const { listRotateableKeys } = require('./key-rotation');
  const keys = listRotateableKeys();

  assert(Array.isArray(keys), 'returns an array');
  assert(keys.includes('ANTHROPIC_API_KEY'),  'includes ANTHROPIC_API_KEY');
  assert(keys.includes('STRIPE_SECRET_KEY'),  'includes STRIPE_SECRET_KEY');
  assert(keys.length === 2, 'returns exactly 2 rotateable keys');

  // Confirm values are not present — only names
  const envRaw = fs.readFileSync(ENV_FILE, 'utf8');
  for (const k of keys) {
    const eqIdx = envRaw.indexOf(`${k}=`);
    const value = envRaw.slice(eqIdx + k.length + 1).split('\n')[0].trim();
    assert(
      !keys.some((entry) => entry === value),
      `listRotateableKeys does not expose value of ${k}`
    );
  }
}

// ── Suite 2: rotateKey — happy path ──────────────────────────────────────────
console.log('\nSuite 2: rotateKey() — happy path');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  // Capture the original value so we can confirm it was replaced
  const envBefore = fs.readFileSync(ENV_FILE, 'utf8');
  const originalAnthropicLine = envBefore
    .split('\n')
    .find((l) => l.startsWith('ANTHROPIC_API_KEY='));
  const originalValue = originalAnthropicLine.split('=').slice(1).join('=');

  const result = rotateKey('ANTHROPIC_API_KEY');

  // Return value must contain only metadata
  assert(typeof result === 'object' && result !== null, 'returns an object');
  assert(result.keyName === 'ANTHROPIC_API_KEY',        'result.keyName is correct');
  assert(typeof result.timestamp === 'string',          'result.timestamp is a string');
  assert(!isNaN(Date.parse(result.timestamp)),          'result.timestamp is a valid ISO date');
  assert(!('placeholder' in result),  'result does NOT expose the new placeholder');
  assert(!('value' in result),        'result does NOT expose any key value');
  assert(!('newValue' in result),     'result does NOT expose newValue');
  assert(!('oldValue' in result),     'result does NOT expose oldValue');

  // .env.test must have been updated
  const envAfter = fs.readFileSync(ENV_FILE, 'utf8');
  const updatedLine = envAfter
    .split('\n')
    .find((l) => l.startsWith('ANTHROPIC_API_KEY='));
  const newValue = updatedLine.split('=').slice(1).join('=');

  assert(newValue !== originalValue, '.env.test value was changed');
  assert(
    newValue.startsWith('ROTATED-ANTHROPIC_API_KEY-'),
    'new value has the expected ROTATED- prefix'
  );
  assert(
    /^ROTATED-ANTHROPIC_API_KEY-[0-9a-f]{32}$/.test(newValue),
    'new value matches ROTATED-<name>-<hex32> format'
  );

  // Other keys must be untouched
  const stripeLineBefore = envBefore.split('\n').find((l) => l.startsWith('STRIPE_SECRET_KEY='));
  const stripeLineAfter  = envAfter.split('\n').find((l) => l.startsWith('STRIPE_SECRET_KEY='));
  assert(stripeLineBefore === stripeLineAfter, 'STRIPE_SECRET_KEY line is untouched');

  const dbLineBefore = envBefore.split('\n').find((l) => l.startsWith('DATABASE_URL='));
  const dbLineAfter  = envAfter.split('\n').find((l) => l.startsWith('DATABASE_URL='));
  assert(dbLineBefore === dbLineAfter, 'DATABASE_URL is untouched');
}

// ── Suite 3: rotateKey — Stripe key ──────────────────────────────────────────
console.log('\nSuite 3: rotateKey() — STRIPE_SECRET_KEY');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  const result = rotateKey('STRIPE_SECRET_KEY');
  assert(result.keyName === 'STRIPE_SECRET_KEY', 'result.keyName is STRIPE_SECRET_KEY');

  const envAfter = fs.readFileSync(ENV_FILE, 'utf8');
  const stripeNewLine  = envAfter.split('\n').find((l) => l.startsWith('STRIPE_SECRET_KEY='));
  const stripeNewValue = stripeNewLine.split('=').slice(1).join('=');

  assert(
    /^ROTATED-STRIPE_SECRET_KEY-[0-9a-f]{32}$/.test(stripeNewValue),
    'STRIPE_SECRET_KEY placeholder has correct format'
  );

  // ANTHROPIC_API_KEY must be untouched
  const anthropicLine = envAfter.split('\n').find((l) => l.startsWith('ANTHROPIC_API_KEY='));
  assert(
    anthropicLine.includes('CANARY'),
    'ANTHROPIC_API_KEY is not modified when rotating STRIPE_SECRET_KEY'
  );
}

// ── Suite 4: rotation-log.json — content audit ───────────────────────────────
console.log('\nSuite 4: rotation-log.json — content audit (no key values)');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');

  assert(fs.existsSync(LOG_FILE), 'rotation-log.json was created');

  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert(Array.isArray(log), 'log is a JSON array');
  assert(log.length === 2,   'log has one entry per rotation');

  // Read the env file to collect all *values* that must NOT appear in the log
  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const allValues = envContent
    .split('\n')
    .filter((l) => l.trim() && !l.trim().startsWith('#') && l.includes('='))
    .map((l) => l.split('=').slice(1).join('=').trim());

  const logRaw = fs.readFileSync(LOG_FILE, 'utf8');

  for (const val of allValues) {
    assert(
      !logRaw.includes(val),
      `log does not contain env value "${val.slice(0, 8)}…" (truncated for display)`
    );
  }

  // Verify required fields are present and correct
  const entry0 = log[0];
  assert(entry0.keyName === 'ANTHROPIC_API_KEY', 'entry 0 keyName is correct');
  assert(entry0.status  === 'success',           'entry 0 status is "success"');
  assert(typeof entry0.timestamp === 'string' && !isNaN(Date.parse(entry0.timestamp)),
    'entry 0 timestamp is a valid ISO date');
  assert(!('value' in entry0),       'entry 0 has no "value" field');
  assert(!('placeholder' in entry0), 'entry 0 has no "placeholder" field');
  assert(!('newValue' in entry0),    'entry 0 has no "newValue" field');
  assert(!('oldValue' in entry0),    'entry 0 has no "oldValue" field');

  const entry1 = log[1];
  assert(entry1.keyName === 'STRIPE_SECRET_KEY', 'entry 1 keyName is correct');
  assert(entry1.status  === 'success',           'entry 1 status is "success"');
}

// ── Suite 5: atomicity — temp file is cleaned up ─────────────────────────────
console.log('\nSuite 5: atomicity — no leftover temp file');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  rotateKey('ANTHROPIC_API_KEY');

  assert(
    !fs.existsSync(ENV_TMP_FILE),
    '.env.test.tmp does not exist after successful rotation'
  );
}

// ── Suite 6: error handling — invalid key name ───────────────────────────────
console.log('\nSuite 6: error handling — invalid key names');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  assertThrows(
    () => rotateKey('AWS_SECRET_ACCESS_KEY'),
    'not a rotateable key',
    'rejects a key name that exists in .env.test but is not in the allowed set'
  );

  assertThrows(
    () => rotateKey('TOTALLY_UNKNOWN_KEY'),
    'not a rotateable key',
    'rejects a key name that does not exist at all'
  );

  assertThrows(
    () => rotateKey(''),
    'non-empty string',
    'rejects an empty string'
  );

  assertThrows(
    () => rotateKey(null),
    'non-empty string',
    'rejects null'
  );

  // .env.test must be completely unchanged after all failed calls
  const envAfter = fs.readFileSync(ENV_FILE, 'utf8');
  assert(envAfter === ORIGINAL_ENV, '.env.test is unchanged after all failed rotations');
}

// ── Suite 7: failure events are logged ───────────────────────────────────────
console.log('\nSuite 7: failure events are written to rotation-log.json');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  try { rotateKey('DOES_NOT_EXIST'); } catch (_) { /* expected */ }

  assert(fs.existsSync(LOG_FILE), 'rotation-log.json created even for failures');
  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert(log.length === 1,              'one failure entry logged');
  assert(log[0].status === 'failure',   'entry status is "failure"');
  assert(typeof log[0].error === 'string' && log[0].error.length > 0,
    'failure entry contains an error message');
  assert(!('value' in log[0]),       'failure entry has no "value" field');
  assert(!('placeholder' in log[0]), 'failure entry has no "placeholder" field');
}

// ── Suite 8: log is append-only (multiple rotations accumulate) ──────────────
console.log('\nSuite 8: log accumulates entries across calls');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');

  for (let i = 0; i < 3; i++) {
    rotateKey('ANTHROPIC_API_KEY');
  }

  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert(log.length === 3, 'all 3 rotation events are present in the log');

  // Timestamps should be non-decreasing
  const times = log.map((e) => Date.parse(e.timestamp));
  assert(
    times[0] <= times[1] && times[1] <= times[2],
    'timestamps are non-decreasing'
  );
}

// ── Suite 9: file permissions ─────────────────────────────────────────────────
console.log('\nSuite 9: file permission checks');
{
  resetFixtures();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');

  const envStat = fs.statSync(ENV_FILE);
  const logStat = fs.statSync(LOG_FILE);

  // Mode bitmask: 0o777 masks off file-type bits; we want 0o600 (owner rw only)
  assert(
    (envStat.mode & 0o777) === 0o600,
    `.env.test permissions are 0o600 (got 0o${(envStat.mode & 0o777).toString(8)})`
  );
  assert(
    (logStat.mode & 0o777) === 0o600,
    `rotation-log.json permissions are 0o600 (got 0o${(logStat.mode & 0o777).toString(8)})`
  );
}

// ─── Final teardown & summary ─────────────────────────────────────────────────

resetFixtures(); // restore original .env.test and remove artefacts

console.log('\n══════════════════════════════════════════════');
console.log(` Results: ${passed} passed, ${failed} failed`);
console.log('══════════════════════════════════════════════\n');

if (failed > 0) process.exit(1);

