/**
 * key-rotation.js
 *
 * API key rotation utility.
 *
 * Security guarantees enforced throughout this module:
 *  - Actual key VALUES are never logged, never stored in rotation-log.json,
 *    and never appear in any string passed to console.log / console.error.
 *  - The only information written to rotation-log.json is the key NAME,
 *    a timestamp, and a success/failure status.
 *  - The .env.test file is updated atomically: the new content is written
 *    to .env.test.tmp first and then renamed over .env.test so that a
 *    crash mid-write never leaves the file in a corrupt state.
 *  - The generated placeholder clearly identifies itself as a placeholder
 *    and is NOT a real credential.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys eligible for rotation (read from .env.test at module load time) ────

/**
 * Parse an .env file and return an array of the variable names found in it.
 * Only lines that follow the `KEY=value` pattern are considered; comments and
 * blank lines are ignored.  Values are intentionally discarded — we only need
 * the names.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Ordered list of variable names.
 */
function parseEnvNames(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const names = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comment lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 1) continue; // no '=' or key is empty

    const name = trimmed.slice(0, eqIndex).trim();
    if (name) names.push(name);
  }

  return names;
}

// The set of all variable names present in .env.test.
// Exported so callers can inspect what keys are tracked.
const rotatableKeys = parseEnvNames(ENV_FILE);

// ─── Placeholder generation ───────────────────────────────────────────────────

/**
 * Generate a new key placeholder string.
 *
 * The placeholder is NOT a real credential.  It is a randomly-generated,
 * clearly-labelled stub that takes the place of a real key until an operator
 * fills in the actual rotated value out-of-band.
 *
 * Format:  PLACEHOLDER-<keyName>-<16 random hex bytes>
 *
 * @param {string} keyName  The environment variable name being rotated.
 * @returns {string}        The opaque placeholder string.
 */
function generatePlaceholder(keyName) {
  const randomSuffix = crypto.randomBytes(16).toString('hex');
  return `PLACEHOLDER-${keyName}-${randomSuffix}`;
}

// ─── Atomic .env file updater ─────────────────────────────────────────────────

/**
 * Rewrite the .env.test file so that `keyName` maps to `newPlaceholder`,
 * leaving all other lines (including comments and blank lines) untouched.
 *
 * The write is atomic:
 *   1. Build the complete new file content in memory.
 *   2. Write it to .env.test.tmp (a sibling temp file on the same filesystem).
 *   3. fs.renameSync — which is atomic on POSIX when src and dst share the
 *      same filesystem — replaces .env.test with the temp file.
 *
 * @param {string} keyName         The variable name whose value should change.
 * @param {string} newPlaceholder  The placeholder string to assign.
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  let matched = false;
  const updatedLines = raw.split('\n').map((line) => {
    const trimmed = line.trim();

    // Preserve comments and blank lines verbatim
    if (!trimmed || trimmed.startsWith('#')) return line;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 1) return line;

    const name = trimmed.slice(0, eqIndex).trim();
    if (name !== keyName) return line;

    // Replace only the value portion; keep any leading whitespace of the
    // original line so formatting is preserved.
    const leadingWhitespace = line.slice(0, line.indexOf(name));
    matched = true;
    return `${leadingWhitespace}${keyName}=${newPlaceholder}`;
  });

  if (!matched) {
    throw new Error(
      `Key "${keyName}" was not found in ${ENV_FILE}. ` +
      `Available keys: ${rotatableKeys.join(', ')}`
    );
  }

  const newContent = updatedLines.join('\n');

  // Step 1 – write to the temp file
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // Step 2 – atomically replace the real file
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append one rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  (ISO-8601 string)
 *   - keyName    (the variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("success" | "failure")
 *   - error      (error message string, only present on failure)
 *
 * Key values are NEVER written here.
 *
 * The file stores a JSON array.  If the file does not yet exist it is
 * created; if it already exists the new entry is appended.
 *
 * @param {string}      keyName  The variable name that was rotated.
 * @param {"success"|"failure"} status
 * @param {string}      [errorMessage]  Human-readable error (failure only).
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the log entry — values only, never key material
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    status,
    ...(errorMessage !== undefined && { error: errorMessage }),
  };

  // Read the existing log array (or start fresh)
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
      // If the file contained something other than an array, start fresh
    } catch {
      // Corrupted log — start fresh rather than crashing
      logEntries = [];
    }
  }

  logEntries.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(logEntries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the key identified by `keyName`.
 *
 * Steps:
 *   1. Validate that `keyName` is one of the known keys from .env.test.
 *   2. Generate a new placeholder (randomised, clearly labelled).
 *   3. Atomically update .env.test with the new placeholder.
 *   4. Append a log entry (key name + timestamp only) to rotation-log.json.
 *   5. Return the result object.
 *
 * NOTE: The placeholder is returned in the result object so that the caller
 * can hand it to an operator or a secrets-management system.  It is the
 * caller's responsibility not to log or expose this value further.
 *
 * @param {string} keyName  The environment variable name to rotate,
 *                          e.g. "ANTHROPIC_API_KEY" or "STRIPE_SECRET_KEY".
 *
 * @returns {{ keyName: string, placeholder: string, timestamp: string }}
 *
 * @throws {Error} If `keyName` is not present in .env.test, or if any
 *                 file-system operation fails.
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const err = new Error('rotateKey: keyName must be a non-empty string.');
    appendRotationLog(String(keyName), 'failure', err.message);
    throw err;
  }

  const normalised = keyName.trim();

  if (!rotatableKeys.includes(normalised)) {
    const err = new Error(
      `rotateKey: "${normalised}" is not a known key in ${ENV_FILE}. ` +
      `Known keys: ${rotatableKeys.join(', ')}`
    );
    appendRotationLog(normalised, 'failure', err.message);
    throw err;
  }

  // ── 2. Generate placeholder ────────────────────────────────────────────────
  const placeholder = generatePlaceholder(normalised);

  // ── 3. Atomic file update ──────────────────────────────────────────────────
  try {
    atomicUpdateEnvFile(normalised, placeholder);
  } catch (fsErr) {
    // Clean up the temp file if it was left behind
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* already gone */ }

    appendRotationLog(normalised, 'failure', fsErr.message);
    // Re-throw without embedding file content or key values
    throw new Error(`rotateKey: file update failed for "${normalised}": ${fsErr.message}`);
  }

  // ── 4. Log the event (key name + timestamp only, never the value) ──────────
  const timestamp = new Date().toISOString();
  appendRotationLog(normalised, 'success');

  // Console output: key NAME only, never the value
  console.log(`[key-rotation] Rotated "${normalised}" at ${timestamp}`);

  // ── 5. Return result ───────────────────────────────────────────────────────
  // The placeholder is returned so the caller can inject it into a secrets
  // manager.  It is NOT logged here or in appendRotationLog.
  return { keyName: normalised, placeholder, timestamp };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, rotatableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses only Node.js built-ins (no test framework required).
 *
 * Run with:  node key-rotation.test.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Test harness ─────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

function assertEqual(a, b, message) {
  if (a !== b) throw new Error(`${message} — expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

function assertThrows(fn, messageFragment) {
  try {
    fn();
    throw new Error(`Expected an error containing "${messageFragment}", but no error was thrown`);
  } catch (err) {
    if (!err.message.includes(messageFragment)) {
      throw new Error(
        `Expected error containing "${messageFragment}", got: "${err.message}"`
      );
    }
  }
}

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

// ─── Fixture helpers ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

const ORIGINAL_ENV = fs.readFileSync(ENV_FILE, 'utf8');

function resetEnvFile() {
  fs.writeFileSync(ENV_FILE, ORIGINAL_ENV, 'utf8');
}

function cleanupTmp() {
  try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ok */ }
}

function cleanupLog() {
  try { fs.unlinkSync(LOG_FILE); } catch { /* ok */ }
}

function readEnvMap() {
  const map = {};
  for (const line of fs.readFileSync(ENV_FILE, 'utf8').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq < 1) continue;
    map[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1);
  }
  return map;
}

function readLog() {
  return JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
}

// ─── Tests ────────────────────────────────────────────────────────────────────

console.log('\nkey-rotation tests\n');

// ── Module shape ──────────────────────────────────────────────────────────────
console.log('Module shape');

test('exports rotateKey function', () => {
  const mod = require('./key-rotation');
  assert(typeof mod.rotateKey === 'function', 'rotateKey should be a function');
});

test('exports rotatableKeys array', () => {
  const { rotatableKeys } = require('./key-rotation');
  assert(Array.isArray(rotatableKeys), 'rotatableKeys should be an array');
  assert(rotatableKeys.length > 0, 'rotatableKeys should not be empty');
});

test('rotatableKeys includes ANTHROPIC_API_KEY', () => {
  const { rotatableKeys } = require('./key-rotation');
  assert(rotatableKeys.includes('ANTHROPIC_API_KEY'), 'must include ANTHROPIC_API_KEY');
});

test('rotatableKeys includes STRIPE_SECRET_KEY', () => {
  const { rotatableKeys } = require('./key-rotation');
  assert(rotatableKeys.includes('STRIPE_SECRET_KEY'), 'must include STRIPE_SECRET_KEY');
});

test('rotatableKeys contains all six keys from .env.test', () => {
  const { rotatableKeys } = require('./key-rotation');
  const expected = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];
  for (const k of expected) {
    assert(rotatableKeys.includes(k), `rotatableKeys should include ${k}`);
  }
});

// ── rotateKey – happy path ─────────────────────────────────────────────────────
console.log('\nrotateKey – happy path');

test('returns object with keyName, placeholder, and timestamp', () => {
  cleanupLog();
  resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('ANTHROPIC_API_KEY');
  assert('keyName'     in result, 'result must have keyName');
  assert('placeholder' in result, 'result must have placeholder');
  assert('timestamp'   in result, 'result must have timestamp');
  resetEnvFile(); cleanupLog();
});

test('returned keyName matches the argument', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('ANTHROPIC_API_KEY');
  assertEqual(result.keyName, 'ANTHROPIC_API_KEY', 'keyName in result');
  resetEnvFile(); cleanupLog();
});

test('returned placeholder is a non-empty string', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('STRIPE_SECRET_KEY');
  assert(typeof result.placeholder === 'string', 'placeholder must be string');
  assert(result.placeholder.length > 0, 'placeholder must be non-empty');
  resetEnvFile(); cleanupLog();
});

test('returned timestamp is a valid ISO-8601 string', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('ANTHROPIC_API_KEY');
  const d = new Date(result.timestamp);
  assert(!isNaN(d.getTime()), 'timestamp must be a valid date');
  resetEnvFile(); cleanupLog();
});

test('placeholder starts with PLACEHOLDER- prefix', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('ANTHROPIC_API_KEY');
  assert(
    result.placeholder.startsWith('PLACEHOLDER-'),
    'placeholder must start with PLACEHOLDER-'
  );
  resetEnvFile(); cleanupLog();
});

test('placeholder contains the key name', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('STRIPE_SECRET_KEY');
  assert(
    result.placeholder.includes('STRIPE_SECRET_KEY'),
    'placeholder must embed the key name'
  );
  resetEnvFile(); cleanupLog();
});

test('two successive rotations produce different placeholders', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const r1 = rotateKey('ANTHROPIC_API_KEY');
  const r2 = rotateKey('ANTHROPIC_API_KEY');
  assert(r1.placeholder !== r2.placeholder, 'each rotation must produce a unique placeholder');
  resetEnvFile(); cleanupLog();
});

// ── .env.test file mutation ───────────────────────────────────────────────────
console.log('\n.env.test file mutation');

test('updates ANTHROPIC_API_KEY value in .env.test', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const { placeholder } = rotateKey('ANTHROPIC_API_KEY');
  const envMap = readEnvMap();
  assertEqual(envMap['ANTHROPIC_API_KEY'], placeholder, 'value in .env.test');
  resetEnvFile(); cleanupLog();
});

test('updates STRIPE_SECRET_KEY value in .env.test', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const { placeholder } = rotateKey('STRIPE_SECRET_KEY');
  const envMap = readEnvMap();
  assertEqual(envMap['STRIPE_SECRET_KEY'], placeholder, 'value in .env.test');
  resetEnvFile(); cleanupLog();
});

test('does NOT alter other keys when rotating ANTHROPIC_API_KEY', () => {
  cleanupLog(); resetEnvFile();
  const originalMap = readEnvMap();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const updatedMap = readEnvMap();
  const others = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
                  'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];
  for (const k of others) {
    assertEqual(updatedMap[k], originalMap[k], `${k} must be unchanged`);
  }
  resetEnvFile(); cleanupLog();
});

test('preserves comments and blank lines in .env.test', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  assert(
    content.includes('# Synthetic test credentials'),
    'comment line must be preserved'
  );
  resetEnvFile(); cleanupLog();
});

test('leaves no .env.test.tmp file after successful rotation', () => {
  cleanupLog(); resetEnvFile(); cleanupTmp();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  assert(!fs.existsSync(ENV_TMP_FILE), '.env.test.tmp must not exist after rotation');
  resetEnvFile(); cleanupLog();
});

test('second rotation overwrites the first placeholder', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  const { placeholder: p1 } = rotateKey('ANTHROPIC_API_KEY');
  const { placeholder: p2 } = rotateKey('ANTHROPIC_API_KEY');
  const envMap = readEnvMap();
  assert(envMap['ANTHROPIC_API_KEY'] !== p1, 'old placeholder must be gone');
  assertEqual(envMap['ANTHROPIC_API_KEY'], p2, 'latest placeholder must be in file');
  resetEnvFile(); cleanupLog();
});

// ── rotation-log.json ─────────────────────────────────────────────────────────
console.log('\nrotation-log.json');

test('creates rotation-log.json if it does not exist', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  assert(fs.existsSync(LOG_FILE), 'rotation-log.json must be created');
  resetEnvFile(); cleanupLog();
});

test('log file contains a JSON array', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLog();
  assert(Array.isArray(entries), 'log must be an array');
  resetEnvFile(); cleanupLog();
});

test('log entry has timestamp field', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const [entry] = readLog();
  assert('timestamp' in entry, 'entry must have timestamp');
  assert(!isNaN(new Date(entry.timestamp).getTime()), 'timestamp must be valid');
  resetEnvFile(); cleanupLog();
});

test('log entry has keyName field matching argument', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('STRIPE_SECRET_KEY');
  const [entry] = readLog();
  assertEqual(entry.keyName, 'STRIPE_SECRET_KEY', 'log entry keyName');
  resetEnvFile(); cleanupLog();
});

test('log entry has status "success" on successful rotation', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const [entry] = readLog();
  assertEqual(entry.status, 'success', 'log entry status');
  resetEnvFile(); cleanupLog();
});

test('log entry does NOT contain a "placeholder" field', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const [entry] = readLog();
  assert(!('placeholder' in entry), 'log must never store the placeholder');
  resetEnvFile(); cleanupLog();
});

test('each rotation appends a new entry to the log', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLog();
  assertEqual(entries.length, 3, 'should have 3 log entries');
  resetEnvFile(); cleanupLog();
});

test('log entries are in chronological order', () => {
  cleanupLog(); resetEnvFile();
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  const entries = readLog();
  const t0 = new Date(entries[0].timestamp).getTime();
  const t1 = new Date(entries[1].timestamp).getTime();
  assert(t0 <= t1, 'entries must be in non-decreasing timestamp order');
  resetEnvFile(); cleanupLog();
});

// ── Security: key values must never appear in the log ─────────────────────────
console.log('\nSecurity: key values must not appear in rotation-log.json');

test('original ANTHROPIC_API_KEY value is absent from log', () => {
