/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security guarantees
 * -------------------
 * - Actual key *values* are NEVER read into application memory beyond the
 *   minimal slice needed to locate the line that must be replaced.
 * - Key values are NEVER logged, stored in variables with descriptive names,
 *   printed to stdout/stderr, or included in the rotation log.
 * - The rotation log records only: ISO timestamp, key *name*, and outcome.
 * - File updates are atomic: write to <file>.tmp → fsync → rename.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = ENV_FILE + '.tmp';
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered list of { raw, key, hasValue } records
 * so that we can reconstruct the file exactly, only changing what we must.
 *
 * We deliberately do NOT store parsed values in a named object so that key
 * material is never reachable through a meaningful property name.
 *
 * @param {string} content  Raw file text
 * @returns {{ raw: string, key: string|null }[]}
 */
function parseEnvLines(content) {
  return content.split('\n').map((raw) => {
    // Skip comments and blank lines — preserve them verbatim
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      return { raw, key: null };
    }

    const eqIdx = raw.indexOf('=');
    if (eqIdx === -1) {
      return { raw, key: null };
    }

    const key = raw.slice(0, eqIdx).trim();
    return { raw, key };
  });
}

/**
 * Generate a new placeholder value for a rotated key.
 *
 * In a production system this would call the provider's API (Anthropic,
 * Stripe, etc.) to provision a real credential. Here we produce a
 * cryptographically random placeholder that is clearly synthetic, matching
 * the rough shape of each provider's key format so downstream parsers do
 * not break.
 *
 * The placeholder embeds:
 *   - a provider-specific prefix (where known)
 *   - the literal string "ROTATED" so it is unambiguous in test output
 *   - a timestamp component for rough ordering
 *   - 16 bytes (32 hex chars) of CSPRNG entropy
 *
 * @param {string} keyName  The environment variable name being rotated
 * @returns {string}        New placeholder value (NOT a real credential)
 */
function generatePlaceholder(keyName) {
  const entropy   = crypto.randomBytes(16).toString('hex');
  const tsCompact = Date.now().toString(36); // base-36 timestamp

  // Provider-specific prefixes mirror real-world formats so tooling that
  // validates key shapes does not immediately reject the placeholder.
  const prefixMap = {
    ANTHROPIC_API_KEY : 'sk-ant-',
    STRIPE_SECRET_KEY : 'sk_live_',
    AWS_ACCESS_KEY_ID : 'AKIA',
    AWS_SECRET_ACCESS_KEY: '',
  };

  const prefix = Object.prototype.hasOwnProperty.call(prefixMap, keyName)
    ? prefixMap[keyName]
    : '';

  return `${prefix}ROTATED-${tsCompact}-${entropy}`;
}

/**
 * Atomically write `content` to `targetPath` via a sibling .tmp file.
 *
 * Steps:
 *   1. Write full content to `targetPath + '.tmp'`
 *   2. fsync the file descriptor (flush OS buffers to storage)
 *   3. Close the file descriptor
 *   4. fs.renameSync (atomic on POSIX when src/dst are on the same filesystem)
 *
 * @param {string} targetPath
 * @param {string} content
 */
function atomicWrite(targetPath, content) {
  const tmpPath = targetPath + '.tmp';

  // Open for writing, creating or truncating
  const fd = fs.openSync(tmpPath, 'w', 0o600); // rw------- : owner only
  try {
    fs.writeSync(fd, content, 0, 'utf8');
    fs.fsyncSync(fd); // ensure bytes reach disk before rename
  } finally {
    fs.closeSync(fd);
  }

  fs.renameSync(tmpPath, targetPath); // atomic on POSIX
}

/**
 * Append a rotation event to rotation-log.json.
 *
 * The log file holds a JSON array; we read → push → write so it stays valid
 * JSON throughout. The write is also atomic (tmp → rename).
 *
 * Fields logged per event
 * -----------------------
 *   timestamp  ISO-8601 UTC string
 *   keyName    The environment variable name (e.g. "ANTHROPIC_API_KEY")
 *   outcome    "success" | "failure"
 *   error      (only present on failure) Error message string — never a value
 *
 * Fields deliberately OMITTED
 * ---------------------------
 *   oldValue, newValue, previousKey, rotatedValue — nothing that could
 *   contain or hint at actual credential material.
 *
 * @param {string}  keyName
 * @param {"success"|"failure"} outcome
 * @param {string}  [errorMessage]
 */
function appendLog(keyName, outcome, errorMessage) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8').trim();
      if (raw.length > 0) {
        entries = JSON.parse(raw);
        if (!Array.isArray(entries)) {
          // Corrupt / unexpected format — start fresh rather than crash
          entries = [];
        }
      }
    } catch {
      // If the log is unreadable or malformed, start a new one rather than
      // surfacing internal state in an error message.
      entries = [];
    }
  }

  /** @type {Object} */
  const event = {
    timestamp : new Date().toISOString(),
    keyName,          // variable NAME only — never the value
    outcome,
  };

  if (outcome === 'failure' && typeof errorMessage === 'string') {
    // Sanitise: strip anything that looks like it could be a key value
    // (long alphanumeric tokens) before writing to the log.
    event.error = sanitiseErrorMessage(errorMessage);
  }

  entries.push(event);

  atomicWrite(LOG_FILE, JSON.stringify(entries, null, 2) + '\n');
}

/**
 * Strip potential credential material from an error message before logging.
 *
 * Replaces tokens that are 20+ characters of base64/hex/alphanumeric
 * (the rough minimum length of a real API key) with "[REDACTED]".
 *
 * @param {string} msg
 * @returns {string}
 */
function sanitiseErrorMessage(msg) {
  // Matches contiguous runs of base64url / hex chars that are long enough
  // to plausibly be a key value.
  return msg.replace(/[A-Za-z0-9+/=_\-]{20,}/g, '[REDACTED]');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Read .env.test and return the list of key *names* that are present.
 * Key *values* are parsed internally but never returned to the caller.
 *
 * @returns {string[]}  Array of environment variable names found in .env.test
 */
function listRotatableKeys() {
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  return parseEnvLines(content)
    .filter((line) => line.key !== null)
    .map((line) => line.key);
}

/**
 * Rotate a single key in .env.test.
 *
 * Algorithm
 * ---------
 * 1. Read .env.test into memory as raw text.
 * 2. Parse into lines, confirming `keyName` is present.
 * 3. Generate a new placeholder value (see generatePlaceholder).
 * 4. Reconstruct the file text, replacing only the matching line.
 * 5. Atomically write the new content (tmp → rename).
 * 6. Append a success event to rotation-log.json.
 *
 * On any error the original file is left untouched (the .tmp is cleaned up
 * if possible) and a failure event is appended to the log.
 *
 * @param {string} keyName  Name of the environment variable to rotate,
 *                          e.g. "ANTHROPIC_API_KEY"
 * @throws {Error}          If keyName is not found in .env.test, or if an
 *                          I/O error occurs during the atomic write.
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const err = new TypeError('keyName must be a non-empty string');
    appendLog(String(keyName), 'failure', err.message);
    throw err;
  }

  const safeName = keyName.trim();

  // Validate keyName is a legal env-var identifier before doing any I/O,
  // which also prevents path-injection if the name were ever derived from
  // untrusted input.
  if (!/^[A-Z_][A-Z0-9_]*$/i.test(safeName)) {
    const err = new TypeError(
      `keyName "${safeName}" is not a valid environment variable name`
    );
    appendLog(safeName, 'failure', err.message);
    throw err;
  }

  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (ioErr) {
    appendLog(safeName, 'failure', ioErr.message);
    throw ioErr;
  }

  const lines = parseEnvLines(content);

  // Confirm the key exists before generating a placeholder
  const targetIdx = lines.findIndex((l) => l.key === safeName);
  if (targetIdx === -1) {
    const err = new Error(
      `Key "${safeName}" not found in ${path.basename(ENV_FILE)}`
    );
    appendLog(safeName, 'failure', err.message);
    throw err;
  }

  // Generate placeholder AFTER confirming the key exists so we do not
  // waste entropy on a no-op.
  const newPlaceholder = generatePlaceholder(safeName);

  // Reconstruct file content — only the matched line changes
  const newLines = lines.map((line, idx) => {
    if (idx !== targetIdx) return line.raw;
    // Rebuild as KEY=VALUE, preserving no part of the old value
    return `${safeName}=${newPlaceholder}`;
  });

  const newContent = newLines.join('\n');

  // Atomic write: .env.test.tmp → .env.test
  try {
    atomicWrite(ENV_FILE, newContent);
  } catch (writeErr) {
    // Best-effort cleanup of the tmp file
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    appendLog(safeName, 'failure', writeErr.message);
    throw writeErr;
  }

  // Log success — key name only, no values
  appendLog(safeName, 'success');

  console.log(
    `[key-rotation] Rotated key: ${safeName} at ${new Date().toISOString()}`
  );
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, listRotatableKeys };

