'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Parse an .env file and return only the variable *names* present in it.
 * Values are read transiently from disk and immediately discarded; they are
 * never stored in a variable or returned to any caller.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Ordered list of variable names found in the file.
 */
function _parseEnvKeyNames(filePath) {
  const rawLines = fs.readFileSync(filePath, 'utf8').split('\n');
  const names = [];

  for (const line of rawLines) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const varName = trimmed.slice(0, eqIndex).trim();
    if (varName) names.push(varName);
  }

  return names;
}

