 * Generate a cryptographically random placeholder for a rotated key.
 * Format: ROTATED-<PREFIX>-<32 hex chars>
 * The prefix is derived from the key name for human readability but contains
 * no secret material.
 *
 * @param {string} keyName  The variable name being rotated (e.g. STRIPE_SECRET_KEY).
 * @returns {string}        The new placeholder value.
 */
function _generatePlaceholder(keyName) {
  // Use only the first word of the key name as a safe, non-sensitive label
  const safeLabel = keyName.replace(/[^A-Z0-9_]/gi, '').slice(0, 20);
  const randomHex = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  return `ROTATED-${safeLabel}-${randomHex}`;
