 * `newPlaceholder`. Uses write-to-tmp + rename so that the file is never
 * partially written.
 *
 * The function reads the file line-by-line and only operates on the matching
 * assignment line; all other lines (including other keys' values) are copied
 * verbatim without ever being stored beyond the scope of this function.
 *
 * @param {string} filePath        Absolute path to the live .env file.
 * @param {string} tmpFilePath     Absolute path for the intermediate tmp file.
 * @param {string} keyName         Variable name whose value should be replaced.
 * @param {string} newPlaceholder  Replacement value (the newly generated placeholder).
 */
function _atomicUpdateEnvFile(filePath, tmpFilePath, keyName, newPlaceholder) {
  const rawLines  = fs.readFileSync(filePath, 'utf8').split('\n');
  let   matched   = false;
  const outLines  = [];

  for (const line of rawLines) {
    const trimmed = line.trim();

