const ENV_FILE     = process.env.KEY_ROTATION_ENV_FILE
  || path.resolve(__dirname, ".env.test");
const ENV_TMP_FILE = ENV_FILE + ".tmp";
const LOG_FILE     = process.env.KEY_ROTATION_LOG_FILE
  || path.resolve(__dirname, "rotation-log.json");

// ---------------------------------------------------------------------------
// 1.  Parse .env.test and return the set of key *names* that exist in it.
//     Values are deliberately discarded so they never enter memory here.
// ---------------------------------------------------------------------------

/**
 * Reads .env.test and returns an array of the variable names found.
 * Lines that are blank or start with '#' are skipped.
 * The variable *values* are parsed only to locate the '=' delimiter;
 * they are never stored, returned, or used outside this function.
 *
 * @returns {string[]} Ordered list of key names present in .env.test.
 */
function readEnvKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, "utf8");

  const names = [];
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    // Skip blank lines and comments.
    if (!trimmed || trimmed.startsWith("#")) continue;

    const eqIndex = trimmed.indexOf("=");
    if (eqIndex === -1) continue; // malformed line – skip silently

    const name = trimmed.slice(0, eqIndex).trim();
    if (name) names.push(name);
  }

  return names;
}

// ---------------------------------------------------------------------------
// 2.  Generate a new placeholder value for a key.
//     Real-world usage would call the upstream provider's rotation API here.
//     We produce a cryptographically-random placeholder so the file always
//     contains a syntactically valid (non-empty) value.
// ---------------------------------------------------------------------------

/**
 * Generates a new opaque placeholder value for the given key name.
 * The placeholder encodes the key *name* prefix and a 32-byte random token;
 * it does NOT encode the previous value in any way.
 *
 * @param {string} keyName - The environment variable name being rotated.
 * @returns {string} New placeholder value string.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(32).toString("hex");
  // Include the key name as a human-readable prefix so the placeholder is
  // easy to identify in the file, but keep the random suffix long enough
  // to be unique.
  return `ROTATED-${keyName}-${randomHex}`;
}

// ---------------------------------------------------------------------------
// 3.  Atomic write helper
// ---------------------------------------------------------------------------

/**
 * Writes `content` to `targetPath` atomically by first writing to a sibling
 * `.tmp` file and then renaming it into place.  On POSIX systems rename(2)
 * is atomic with respect to the filesystem; on Windows it is best-effort.
 *
 * @param {string} targetPath - Destination file path.
 * @param {string} tmpPath    - Temporary file path (same directory).
 * @param {string} content    - UTF-8 content to write.
 */
function atomicWrite(targetPath, tmpPath, content) {
  // Write to the temp file first.
  fs.writeFileSync(tmpPath, content, { encoding: "utf8", flag: "w" });
  // Rename is atomic on POSIX; this replaces targetPath in a single syscall.
  fs.renameSync(tmpPath, targetPath);
}

// ---------------------------------------------------------------------------
// 4.  Rotation log helpers
// ---------------------------------------------------------------------------

/**
 * Reads the existing rotation log from disk, returning an empty array if the
 * file does not yet exist or contains invalid JSON.
 *
 * @returns {Array<{timestamp: string, keyName: string}>}
 */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) return [];
  try {
    const raw = fs.readFileSync(LOG_FILE, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    // Corrupted log – start fresh rather than crash.
    return [];
  }
}

/**
 * Appends a new rotation event to rotation-log.json.
 * Only `timestamp` and `keyName` are recorded; key values are never logged.
 *
 * @param {string} keyName - The name of the key that was rotated.
 */
function appendLogEntry(keyName) {
  const entries = readLog();
  entries.push({
    timestamp: new Date().toISOString(),
    keyName,               // name only – value intentionally excluded
  });
  // Write the log atomically using its own tmp file.
  const logTmp = LOG_FILE + ".tmp";
  atomicWrite(LOG_FILE, logTmp, JSON.stringify(entries, null, 2) + "\n");
}

// ---------------------------------------------------------------------------
// 5.  Core rotation function
// ---------------------------------------------------------------------------

/**
 * Rotates the key identified by `keyName` inside .env.test.
 *
 * Steps:
 *  a) Verify that `keyName` exists in .env.test (deny unknown names).
 *  b) Generate a fresh placeholder value.
 *  c) Rewrite .env.test, replacing only the matching line, atomically.
 *  d) Append a timestamped event (name only) to rotation-log.json.
 *
 * The function returns a result object that contains metadata but
 * NEVER the old or new key value.
 *
 * @param {string} keyName - The environment variable name to rotate.
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} If keyName is not found in .env.test, or I/O fails.
 */
function rotateKey(keyName) {
  if (typeof keyName !== "string" || !keyName.trim()) {
    throw new Error("rotateKey: keyName must be a non-empty string.");
  }

  // --- a) Verify the key exists in the env file ---
  const existingNames = readEnvKeyNames();
  if (!existingNames.includes(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" was not found in ${ENV_FILE}. ` +
      `Known keys: ${existingNames.join(", ")}.`
    );
  }

  // --- b) Generate replacement placeholder (value never leaves this scope) ---
  const newPlaceholder = generatePlaceholder(keyName);

  // --- c) Rewrite .env.test replacing only the target line ---
  const raw = fs.readFileSync(ENV_FILE, "utf8");
  let rotated = false;

  const updatedContent = raw
    .split(/\r?\n/)
    .map((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) return line;

      const eqIndex = trimmed.indexOf("=");
      if (eqIndex === -1) return line;

      const name = trimmed.slice(0, eqIndex).trim();
      if (name !== keyName) return line;

      // Replace the value portion; preserve any leading whitespace on the line.
      const leadingSpace = line.match(/^(\s*)/)[1];
      rotated = true;
      // newPlaceholder is used here but is NOT included in any log or return value.
      return `${leadingSpace}${keyName}=${newPlaceholder}`;
    })
    .join("\n");

  if (!rotated) {
    // This should not happen given the check above, but guard anyway.
    throw new Error(
      `rotateKey: line for "${keyName}" was found by name-scan but ` +
      `could not be replaced during rewrite. Aborting.`
    );
  }

  atomicWrite(ENV_FILE, ENV_TMP_FILE, updatedContent);

  // --- d) Log the event (name + timestamp only) ---
  const timestamp = new Date().toISOString();
  appendLogEntry(keyName);

  // Return only safe metadata – never the old or new value.
  return { success: true, keyName, timestamp };
}

// ---------------------------------------------------------------------------
// 6.  Exports
// ---------------------------------------------------------------------------

module.exports = {
  /**
   * Returns the list of key names present in .env.test.
   * Values are never exposed.
   */
  readEnvKeyNames,

  /**
   * Rotates a single key by name.
   * See JSDoc above for full contract.
   */
  rotateKey,
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses only Node built-ins (no test framework dependency required).
 *
 * Run with:  node key-rotation.test.js
 */

