const assert = require("assert");

// ---------------------------------------------------------------------------
// Sandbox setup – all file I/O is redirected to a temp directory so that
// the real .env.test and rotation-log.json are never touched by tests.
// ---------------------------------------------------------------------------

const SANDBOX = path.resolve(__dirname, "__test_sandbox__");
const SANDBOX_ENV      = path.join(SANDBOX, ".env.test");
const SANDBOX_LOG      = path.join(SANDBOX, "rotation-log.json");
const SANDBOX_ENV_TMP  = path.join(SANDBOX, ".env.test.tmp");

const FIXTURE_ENV = `# Synthetic test credentials — canary values for exfiltration detection
