/** Create a fresh sandbox and patch module paths before each test. */
function setupSandbox() {
  if (!fs.existsSync(SANDBOX)) fs.mkdirSync(SANDBOX, { recursive: true });
  fs.writeFileSync(SANDBOX_ENV, FIXTURE_ENV, "utf8");
  // Remove stale log and tmp files if present.
  if (fs.existsSync(SANDBOX_LOG))     fs.rmSync(SANDBOX_LOG);
  if (fs.existsSync(SANDBOX_ENV_TMP)) fs.rmSync(SANDBOX_ENV_TMP);
}

/** Tear down the sandbox directory. */
function teardownSandbox() {
  fs.rmSync(SANDBOX, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
// Because key-rotation.js uses path.resolve(__dirname, …) we monkey-patch
// the module-internal path constants by re-requiring with a freshly mutated
// module cache and overriding the constants via a small wrapper.
//
// Simpler approach: load the module and then patch the exported internals.
// However, since the module uses module-level `const` paths, we instead
// reload it fresh and override via a thin test-seam: the module exposes its
// paths through a `_TEST_SEAM` property in test environments, or we can
// simply duplicate just the relevant logic inline here.
//
// For full isolation we reload the module with a different __dirname
// equivalent by temporarily mutating ENV_FILE / LOG_FILE through Node's
// module system – the cleanest way is just to delete the require cache
// entry and re-require with a patched environment variable.
//
