// injecting them via environment variables that the module checks when
// present.
// ---------------------------------------------------------------------------

// We patch the module by setting env vars that key-rotation.js respects.
// (See the _pathsFromEnv() helper at the bottom of key-rotation.js — we add
// that support now.)  Because we wrote key-rotation.js ourselves we add a
// lightweight test-seam: honour KEY_ROTATION_ENV_FILE and
// KEY_ROTATION_LOG_FILE when set.

// ── Reload the module with sandbox paths ──────────────────────────────────
function loadModule() {
  // Clear the require cache so each test group starts with a fresh module.
  const modPath = require.resolve("./key-rotation.js");
  delete require.cache[modPath];

  process.env.KEY_ROTATION_ENV_FILE = SANDBOX_ENV;
  process.env.KEY_ROTATION_LOG_FILE = SANDBOX_LOG;

  return require("./key-rotation.js");
}

// ---------------------------------------------------------------------------
// Test runner
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    setupSandbox();
    fn(loadModule());
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`     ${err.message}`);
    failed++;
  } finally {
