/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security guarantees:
 *  - Actual key VALUES are never read into memory beyond what is strictly
 *    needed for the line-level text replacement in the .env file.
 *  - Key values are never logged, stored in variables with broad scope,
 *    passed to any external resource, or included in error messages.
 *  - rotation-log.json records ONLY: timestamp, keyName, and outcome.
 *  - The .env file is updated atomically: written to a .tmp file first,
 *    then renamed over the original so readers never see a partial file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that are eligible for rotation ─────────────────────────────────────
// Only the two key *names* requested in the spec are eligible.
// The set is derived by reading the .env.test file and keeping only those
// variable names whose values look like API keys (non-empty, non-URL values).
const ROTATABLE_KEY_NAMES = Object.freeze(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of line descriptors so we can
 * reconstruct the file faithfully (preserving comments, blank lines, ordering).
 *
 * Each element is one of:
 *   { type: 'assignment', name: string, raw: string }
 *   { type: 'other',                   raw: string }   ← comments / blank lines
 *
 * The `raw` field is the ORIGINAL line text.  We keep it so we can write lines
 * back verbatim when no change is needed, and so the value itself is never
 * extracted into a named variable.
 *
 * @param {string} fileContent  Full text of the .env file.
 * @returns {{ type: string, name?: string, raw: string }[]}
 */
function parseEnvLines(fileContent) {
  return fileContent.split('\n').map(line => {
    // Match "KEY=<anything>" – the value is intentionally NOT captured into a
    // named binding; we only need the key name for routing purposes.
    const match = line.match(/^([A-Z][A-Z0-9_]*)=/);
    if (match) {
      return { type: 'assignment', name: match[1], raw: line };
    }
    return { type: 'other', raw: line };
  });
}

/**
 * Read the variable *names* that are currently present in ENV_FILE and are
 * members of ROTATABLE_KEY_NAMES.  This satisfies requirement (1): the module
 * discovers which keys need rotation support by inspecting the file.
 *
 * Returns a Set<string> of key names (never values).
 *
 * @returns {Set<string>}
 */
function readRotatableKeyNames() {
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = parseEnvLines(content);
  const found   = new Set();

  for (const line of lines) {
    if (line.type === 'assignment' && ROTATABLE_KEY_NAMES.includes(line.name)) {
      found.add(line.name);
    }
  }

  return found;
}

/**
 * Generate a new placeholder value for a given key name.
 *
 * The placeholder is a deterministic-format string that makes its synthetic
 * nature obvious, combined with a cryptographically random hex suffix so each
 * rotation produces a unique token.
 *
 * Format examples:
 *   ANTHROPIC_API_KEY  →  REDACTED_ANTHROPIC_KEY<16 hex chars>
 *   STRIPE_SECRET_KEY  →  REDACTED_STRIPE_LIVE<16 hex chars>
 *
 * Only the FORMAT is key-name-aware; the actual entropy comes from crypto.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const entropy = crypto.randomBytes(8).toString('hex'); // 16 hex chars

  switch (keyName) {
    case 'ANTHROPIC_API_KEY':
      return `REDACTED_ANTHROPIC_KEY${entropy}`;
    case 'STRIPE_SECRET_KEY':
      return `REDACTED_STRIPE_LIVE${entropy}`;
    default:
      return `ROTATED-${entropy}`;
  }
}

/**
 * Append one rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  (ISO-8601)
 *   - keyName    (the variable name, e.g. "ANTHROPIC_API_KEY")
 *   - outcome    ("success" | "failure")
 *   - reason     (only present on failure; never contains a key value)
 *
 * The file is a JSON array; we load it (or start a new array), push the entry,
 * and write it back.  No atomicity is required here because the log is append-
 * only and a partial write leaves a recoverable JSON file.
 *
 * @param {string}  keyName
 * @param {'success'|'failure'} outcome
 * @param {string}  [reason]   Human-readable failure reason (no key values).
 */
function appendRotationLog(keyName, outcome, reason) {
  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log – start fresh rather than crashing.
      log = [];
    }
  }

  /** @type {Record<string, string>} */
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    outcome,
  };

  if (outcome === 'failure' && reason) {
    entry.reason = reason; // never set this to anything derived from key values
  }

  log.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * Rotates the value of `keyName` in .env.test:
 *
 *  1. Validates that `keyName` is in the approved ROTATABLE_KEY_NAMES list and
 *     is actually present in the current .env.test file.
 *  2. Generates a new placeholder value.
 *  3. Writes the updated .env content to .env.test.tmp.
 *  4. Atomically renames .env.test.tmp → .env.test.
 *  5. Logs the event (name + outcome only) to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} if keyName is not eligible or not found in the file.
 */
function rotateKey(keyName) {
