  if (typeof keyName !== 'string' || !keyName.trim()) {
    const msg = 'rotateKey: keyName must be a non-empty string.';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  if (!ROTATABLE_KEY_NAMES.includes(keyName)) {
    const msg = `rotateKey: "${keyName}" is not in the approved rotation list ` +
                `(${ROTATABLE_KEY_NAMES.join(', ')}).`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  const presentKeys = readRotatableKeyNames();
  if (!presentKeys.has(keyName)) {
    const msg = `rotateKey: "${keyName}" was not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── Step 2: Generate a new placeholder ────────────────────────────────────
  //
  // The placeholder is stored only in this local `newPlaceholder` variable and
  // is written directly into the reconstructed file text.  It is NOT logged.
  const newPlaceholder = generatePlaceholder(keyName);

  // ── Step 3: Rebuild the .env content with the new placeholder ─────────────
  const originalContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines           = parseEnvLines(originalContent);
  let   replaced        = false;

  const updatedLines = lines.map(line => {
    if (line.type === 'assignment' && line.name === keyName) {
      replaced = true;
      // Construct the new line from the key name + new placeholder ONLY.
      // The old value (line.raw.slice(keyName.length + 1)) is never extracted.
      return `${keyName}=${newPlaceholder}`;
    }
    return line.raw;
  });

  if (!replaced) {
    // Should not happen after the check above, but guard defensively.
    const msg = `rotateKey: replacement line for "${keyName}" was not written — ` +
                'no changes made.';
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  const updatedContent = updatedLines.join('\n');

