'use strict';

/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security guarantees:
 *   - Actual key *values* are NEVER logged, stored in the rotation log,
 *     or written to any variable that could be serialised.
 *   - Only key *names* (the left-hand side of FOO=BAR) are recorded.
 *   - .env.test is updated atomically: content is written to a temp file
 *     first, then the temp file is renamed over the target in a single
 *     syscall, preventing partial-write corruption or torn reads.
 */

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP      = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is authorised to rotate ───────────────────────────
// Sourced exclusively from the names (left-hand side) found in .env.test;
// no values are read at module load time.

const ROTATEABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse .env.test into an ordered array of line descriptors so that we can
 * reconstruct the file without changing whitespace, blank lines, or comments.
 *
 * Each element is one of:
 *   { type: 'raw',     text: '<original line>' }   — comments / blanks
 *   { type: 'entry',   name: '<KEY>', value: '<VALUE>', text: '<original line>' }
 *
 * The value is held only in memory for the duration of the parse/write cycle
 * and is never written to any log or secondary storage.
 */
function parseEnvFile(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  return raw.split('\n').map(line => {
    // Skip comment lines and blank lines – preserve them verbatim.
    if (/^\s*(#|$)/.test(line)) {
      return { type: 'raw', text: line };
    }

    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)/);
    if (!match) {
      return { type: 'raw', text: line };
    }

    return { type: 'entry', name: match[1], value: match[2], text: line };
  });
}

/**
 * Serialise a parsed line array back to a .env file string.
 * For rotated entries the new value is substituted; everything else is
 * reproduced verbatim from `text`.
 */
function serialiseEnvLines(lines) {
  return lines.map(line => {
    if (line.type === 'entry' && line._newValue !== undefined) {
      return `${line.name}=${line._newValue}`;
    }
    return line.text;
  }).join('\n');
}

/**
 * Generate a new key placeholder.
 *
 * The placeholder is a random, unpredictable hex token prefixed with a
 * tag so it is clearly identifiable as a rotated placeholder rather than
 * a real credential.  It is NOT a real API key – in a production system
 * this function would call the relevant vendor SDK / API to issue the key
 * and return only the opaque identifier suitable for storage.
 *
 * Format:  ROTATED-<keyName>-<timestamp_ms>-<16 random bytes as hex>
 *
 * The value is intentionally never logged anywhere in this module.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  const ts        = Date.now();
  return `ROTATED-${keyName}-${ts}-${randomHex}`;
}

/**
 * Append a rotation event to rotation-log.json.
 *
 * Logged fields:
 *   timestamp  – ISO-8601 wall-clock time
 *   keyName    – the environment variable name  (e.g. "ANTHROPIC_API_KEY")
 *   event      – always "rotated"
 *
 * The new (or old) key VALUE is deliberately absent.
 */
function appendRotationLog(keyName) {
  const event = {
    timestamp: new Date().toISOString(),
    keyName,
    event: 'rotated',
  };

  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // If the log is corrupted we start a fresh one rather than failing.
      log = [];
    }
  }

  log.push(event);
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Read .env.test and return the Set of key names that are present in the file
 * AND are in the ROTATEABLE_KEYS allow-list.
 *
 * This is the "discovery" step described in requirement (1).
 * Values are intentionally not returned.
 *
 * @returns {Set<string>}
 */
function getSupportedKeys() {
  const lines   = parseEnvFile(ENV_FILE);
  const present = new Set(
    lines
      .filter(l => l.type === 'entry' && ROTATEABLE_KEYS.has(l.name))
      .map(l => l.name)
  );
  return present;
}

/**
 * Rotate a single key inside .env.test.
 *
 * Steps:
 *   1. Validate that keyName is in the rotateable allow-list.
 *   2. Validate that keyName actually exists in .env.test.
 *   3. Generate a new placeholder value (random, unpredictable).
 *   4. Build the new file content in memory.
 *   5. Write to .env.test.tmp  (atomic write step A).
 *   6. Rename .env.test.tmp → .env.test  (atomic write step B — single syscall).
 *   7. Log the event (name + timestamp only, NO value) to rotation-log.json.
 *
 * @param {string} keyName  – The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation.  The new value is intentionally omitted
 *   from the return object so callers cannot accidentally log it.
 *
 * @throws {Error} if keyName is not in the allow-list or not found in .env.test.
 */
function rotateKey(keyName) {
  // ── 1. Allow-list check ────────────────────────────────────────────────────
  if (!ROTATEABLE_KEYS.has(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" is not in the rotateable allow-list. ` +
      `Supported keys: ${[...ROTATEABLE_KEYS].join(', ')}`
    );
  }

  // ── 2. Parse the current .env.test ────────────────────────────────────────
  const lines = parseEnvFile(ENV_FILE);

  const targetLine = lines.find(l => l.type === 'entry' && l.name === keyName);
  if (!targetLine) {
    throw new Error(
      `rotateKey: "${keyName}" was not found in ${ENV_FILE}.`
    );
  }

  // ── 3. Generate new placeholder ───────────────────────────────────────────
  // The value is bound to a local const; it flows only into the file write
  // below and is not passed to any logger or returned to the caller.
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 4. Stamp the new value onto the parsed line (in-memory only) ──────────
  targetLine._newValue = newPlaceholder;

  // ── 5. Write to temp file ─────────────────────────────────────────────────
  const newContent = serialiseEnvLines(lines);

  // Use 0o600 so the temp file is owner-read/write only from creation.
  fs.writeFileSync(ENV_TMP, newContent, { encoding: 'utf8', mode: 0o600 });

  // ── 6. Atomic rename (single syscall, no window where file is absent) ─────
  fs.renameSync(ENV_TMP, ENV_FILE);

  // ── 7. Log the event (name + timestamp, NOT the value) ───────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName);

  // Clear the in-memory value reference immediately after use.
  targetLine._newValue = undefined;

  console.log(`[key-rotation] Rotated ${keyName} at ${timestamp}`);

  // Return only non-sensitive metadata.
  return { keyName, timestamp };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, getSupportedKeys, ROTATEABLE_KEYS };

