/**
 * key-rotation.js
 *
 * API-key rotation module.
 *
 * Security guarantees
 * -------------------
 *  • Actual key VALUES are never logged, printed, or included in any output.
 *  • Only key NAMES (e.g. "ANTHROPIC_API_KEY") are written to the log.
 *  • The .env.test file is updated atomically: a temporary file is written
 *    first, then renamed over the original so a crash mid-write cannot leave
 *    the env file in a corrupt state.
 *  • The rotation log (rotation-log.json) records only: timestamp, keyName,
 *    and a status field.  No secrets ever touch it.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// Keys this module is authorised to rotate (read from .env.test at start-up).
// Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are in scope per the task spec.
const ROTATABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ─── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of line-descriptor objects so that
 * comments, blank lines, and non-rotatable assignments are preserved verbatim.
 *
 * Each element is one of:
 *   { type: 'assignment', key: string, raw: string }   – KEY=VALUE line
 *   { type: 'other',                   raw: string }   – comment / blank line
 *
 * @param {string} filePath
 * @returns {{ type: string, key?: string, raw: string }[]}
 */
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  return content.split('\n').map(line => {
    // Match lines of the form KEY=... (key may not start with #)
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      return { type: 'assignment', key: match[1], raw: line };
    }
    return { type: 'other', raw: line };
  });
}

/**
 * Serialise the line-descriptor array back to a .env string.
 *
 * @param {{ type: string, key?: string, raw: string }[]} lines
 * @returns {string}
 */
function serializeEnvLines(lines) {
  return lines.map(l => l.raw).join('\n');
}

/**
 * Extract only the key NAMES that are present in the parsed env file AND
 * belong to ROTATABLE_KEYS.  No values are returned.
 *
 * @param {{ type: string, key?: string }[]} lines
 * @returns {string[]}
 */
function extractRotatableKeyNames(lines) {
  return lines
    .filter(l => l.type === 'assignment' && ROTATABLE_KEYS.has(l.key))
    .map(l => l.key);
}

/**
 * Generate a new placeholder value for a rotated key.
 *
 * The placeholder is deliberately NOT a real credential.  It signals that
 * a real secret must be injected by the secrets-management pipeline before
 * the application starts.  The random hex suffix makes each placeholder
 * unique so rotation events are distinguishable without leaking secrets.
 *
 * Format:  ROTATED-<keyName>-<16-hex-chars>
 * Example: ROTATED-ANTHROPIC_API_KEY-3a9f1c0e4d7b82e5
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const suffix = crypto.randomBytes(8).toString('hex'); // 16 hex chars
  return `ROTATED-${keyName}-${suffix}`;
}

/**
 * Append a rotation event to rotation-log.json.
 * Only the key NAME and metadata are recorded — never the value.
 *
 * @param {string} keyName
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage]  — sanitised error description (no secrets)
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Load existing log array, or start fresh.
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Malformed log — start a new array but do not crash the rotation.
      entries = [];
    }
  }

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,          // ONLY the variable name, e.g. "ANTHROPIC_API_KEY"
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  entries.push(entry);

  // Write the log.  The log file is not atomically renamed because a corrupt
  // log is non-critical; a corrupt .env file is critical.
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ────────────────────────────────────────────────────────────────

/**
 * Read .env.test and return the names of the keys that are eligible for
 * rotation (intersection of ROTATABLE_KEYS and keys actually present in the
 * file).  No values are returned.
 *
 * @returns {string[]}  Array of key names, e.g. ["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY"]
 */
function getRotatableKeyNames() {
  const lines = parseEnvFile(ENV_FILE);
  return extractRotatableKeyNames(lines);
}

/**
 * Rotate a single key in .env.test.
 *
 * Steps
 * -----
 * 1. Validate that keyName is in the ROTATABLE_KEYS allow-list.
 * 2. Parse .env.test into line descriptors.
 * 3. Confirm the key is actually present in the file.
 * 4. Generate a new placeholder value (no real secret).
 * 5. Rebuild the file content with the placeholder substituted in-place,
 *    preserving every other line exactly (comments, blanks, other keys).
 * 6. Write the new content to .env.test.tmp, then rename it over .env.test
 *    (atomic on POSIX systems; near-atomic on Windows via NTFS replace).
 * 7. Log the rotation event (key name + timestamp only) to rotation-log.json.
 *
 * @param {string} keyName  The env variable name to rotate, e.g. "ANTHROPIC_API_KEY"
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} If keyName is not in the allow-list or not found in .env.test
 */
function rotateKey(keyName) {
  // ── Step 1: Allow-list check ─────────────────────────────────────────────
  if (!ROTATABLE_KEYS.has(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not in the rotatable-keys allow-list. ` +
      `Allowed keys: ${[...ROTATABLE_KEYS].join(', ')}`
    );
    // Log the failed attempt (key name only — no value involved here anyway).
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  // ── Step 2: Parse the current env file ───────────────────────────────────
  let lines;
  try {
    lines = parseEnvFile(ENV_FILE);
  } catch (readErr) {
    const msg = `rotateKey: could not read ${ENV_FILE}: ${readErr.message}`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── Step 3: Confirm the key exists in the file ───────────────────────────
  const keyLine = lines.find(l => l.type === 'assignment' && l.key === keyName);
  if (!keyLine) {
    const msg = `rotateKey: key "${keyName}" not found in ${ENV_FILE}`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── Step 4: Generate a placeholder (not a real secret) ───────────────────
  const placeholder = generatePlaceholder(keyName);

  // ── Step 5: Rebuild content, replacing only this key's line ──────────────
  //    We mutate a copy of the raw string — the old value is discarded
  //    immediately and is never stored in any variable after this point.
  const updatedLines = lines.map(l => {
    if (l.type === 'assignment' && l.key === keyName) {
      return { ...l, raw: `${keyName}=${placeholder}` };
    }
    return l;
  });

  const newContent = serializeEnvLines(updatedLines);

  // ── Step 6: Atomic write ─────────────────────────────────────────────────
  try {
    // Write to the temp file first.
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    // Atomically rename temp → target.
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (writeErr) {
    // Clean up the temp file if it exists so we don't leave debris.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    const msg = `rotateKey: atomic write failed for "${keyName}": ${writeErr.message}`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── Step 7: Log the event (name + timestamp only, no value) ──────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  console.log(`[key-rotation] Rotated key "${keyName}" at ${timestamp}. ` +
              `Event recorded in ${path.basename(LOG_FILE)}.`);

  return { success: true, keyName, timestamp };
}

// ─── Module exports ────────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotatableKeyNames };

