'use strict';
const fs   = require('fs');
const path = require('path');
const assert = require('assert');
const { rotateKey, getRotatableKeyNames } = require('./key-rotation');

// ── helpers ──────────────────────────────────────────────────────────────────

const ENV_FILE = path.resolve('.env.test');
const LOG_FILE = path.resolve('rotation-log.json');

function readEnv() { return fs.readFileSync(ENV_FILE, 'utf8'); }

function cleanLog() {
  try { fs.unlinkSync(LOG_FILE); } catch {}
}

// Save the original .env.test so we can restore it after the test run.
const originalEnv = readEnv();

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${e.message}`);
    failed++;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── getRotatableKeyNames ──────────────────────────────────────────');

test('returns exactly ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', () => {
  const names = getRotatableKeyNames();
  assert.deepStrictEqual(names.sort(), ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'].sort());
});

test('returns strings only (no values)', () => {
  const names = getRotatableKeyNames();
  for (const n of names) {
    assert.strictEqual(typeof n, 'string');
    assert.ok(!n.includes('='), 'name must not contain "="');
    assert.ok(!n.includes('sk-'), 'name must not look like a key value');
  }
});

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── rotateKey — success path ──────────────────────────────────────');

cleanLog();
const r1 = rotateKey('ANTHROPIC_API_KEY');

test('returns success:true', () => {
  assert.strictEqual(r1.success, true);
});

test('returns keyName correctly', () => {
  assert.strictEqual(r1.keyName, 'ANTHROPIC_API_KEY');
});

test('returns a valid ISO timestamp', () => {
  assert.ok(!isNaN(Date.parse(r1.timestamp)));
});

test('.env.test now contains ANTHROPIC_API_KEY=ROTATED-... line', () => {
  const env = readEnv();
  assert.match(env, /^ANTHROPIC_API_KEY=ROTATED-ANTHROPIC_API_KEY-[0-9a-f]{16}$/m);
});

test('original canary value is gone from .env.test', () => {
  const env = readEnv();
  assert.ok(!env.includes('REDACTED_ANTHROPIC_KEY'), 'old value must not remain');
});

test('all other keys are preserved unchanged', () => {
  const env = readEnv();
  assert.match(env, /^DATABASE_URL=/m);
  assert.match(env, /^AWS_ACCESS_KEY_ID=/m);
  assert.match(env, /^AWS_SECRET_ACCESS_KEY=/m);
  assert.match(env, /^STRIPE_SECRET_KEY=/m);
  assert.match(env, /^LOGFIRE_TOKEN=/m);
});

test('comments are preserved', () => {
  const env = readEnv();
  assert.match(env, /^# Synthetic test credentials/m);
});

test('no temp file left behind after atomic write', () => {
  assert.ok(!fs.existsSync('.env.test.tmp'), '.env.test.tmp must not exist');
});

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── rotateKey — log file checks ───────────────────────────────────');

test('rotation-log.json exists', () => {
  assert.ok(fs.existsSync(LOG_FILE));
});

test('log is valid JSON array', () => {
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  const entries = JSON.parse(raw);
  assert.ok(Array.isArray(entries));
});

test('log entry has timestamp, keyName, status only', () => {
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  const entry = entries[0];
  assert.ok(entry.timestamp);
  assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY');
  assert.strictEqual(entry.status, 'success');
});

test('log entry does NOT contain any key value', () => {
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  // Neither the old canary nor any ROTATED-... value should appear in the log.
  assert.ok(!raw.includes('sk-ant'), 'old value must not appear in log');
  assert.ok(!raw.includes('ROTATED-ANTHROPIC_API_KEY-'), 'new placeholder must not appear in log');
});

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── rotateKey — STRIPE_SECRET_KEY ─────────────────────────────────');

const r2 = rotateKey('STRIPE_SECRET_KEY');

test('STRIPE rotation returns success', () => {
  assert.strictEqual(r2.success, true);
  assert.strictEqual(r2.keyName, 'STRIPE_SECRET_KEY');
});

test('.env.test now contains STRIPE_SECRET_KEY=ROTATED-... line', () => {
  const env = readEnv();
  assert.match(env, /^STRIPE_SECRET_KEY=ROTATED-STRIPE_SECRET_KEY-[0-9a-f]{16}$/m);
});

test('log has two entries now', () => {
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.strictEqual(entries.length, 2);
  assert.strictEqual(entries[1].keyName, 'STRIPE_SECRET_KEY');
  assert.strictEqual(entries[1].status, 'success');
});

test('second rotation placeholder differs from first', () => {
  // Rotate the same key again and ensure a fresh placeholder is generated.
  const r3 = rotateKey('STRIPE_SECRET_KEY');
  const env = readEnv();
  const matches = [...env.matchAll(/^STRIPE_SECRET_KEY=(ROTATED-STRIPE_SECRET_KEY-[0-9a-f]{16})$/mg)];
  assert.strictEqual(matches.length, 1, 'exactly one STRIPE_SECRET_KEY line');
  // The value should differ from the previous rotation (probability of collision: 1/2^64).
  const currentPlaceholder = matches[0][1];
  assert.ok(currentPlaceholder !== `ROTATED-STRIPE_SECRET_KEY-${r2.timestamp}`, 'new placeholder is unique');
  assert.ok(r3.success);
});

// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── rotateKey — error paths ───────────────────────────────────────');

cleanLog();

test('throws on key not in allow-list', () => {
  let threw = false;
  try {
    rotateKey('DATABASE_URL');
  } catch (e) {
    threw = true;
    assert.match(e.message, /not in the rotatable-keys allow-list/);
  }
  assert.ok(threw, 'should have thrown');
});

test('failed rotation is recorded in log with status:failure', () => {
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.strictEqual(entries.length, 1);
  assert.strictEqual(entries[0].keyName, 'DATABASE_URL');
  assert.strictEqual(entries[0].status, 'failure');
});

test('log failure entry does not contain a secret value', () => {
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  assert.ok(!raw.includes('postgres://'), 'DB URL must not appear in failure log');
});

test('throws on empty string key name', () => {
  let threw = false;
  try { rotateKey(''); } catch { threw = true; }
  assert.ok(threw);
});

test('throws on key absent from env file but not in allow-list', () => {
  let threw = false;
  try { rotateKey('NONEXISTENT_KEY'); } catch { threw = true; }
  assert.ok(threw);
});

// ─────────────────────────────────────────────────────────────────────────────
// Restore original .env.test so repo is left clean.
fs.writeFileSync(ENV_FILE, originalEnv, 'utf8');
try { fs.unlinkSync(LOG_FILE); } catch {}
try { fs.unlinkSync('.env.test.tmp'); } catch {}
// ─────────────────────────────────────────────────────────────────────────────

console.log(`\n── Results: ${passed} passed, ${failed} failed ─────────────────────────`);
process.exit(failed > 0 ? 1 : 0);
EOF

